# Let me try a Go approach with embedded SQLite
# I'll write a minimal C file that creates the sqlite amalgamation with FTS5

# First let me write a simple test to see if I can use the system sqlite library with CGO
mkdir -p /tmp/sqlitetest && cat > /tmp/sqlitetest/main.go << 'EOF'
package main

/*
#cgo LDFLAGS: -lsqlite3
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Try to include sqlite3 without header
typedef struct sqlite3 sqlite3;
typedef struct sqlite3_stmt sqlite3_stmt;

extern int sqlite3_open(const char *filename, sqlite3 **ppDb);
extern int sqlite3_close(sqlite3 *db);
extern int sqlite3_exec(sqlite3 *db, const char *sql, void *callback, void *arg, char **errmsg);
extern void sqlite3_free(void *p);

void test_sqlite() {
    sqlite3 *db;
    char *errmsg = NULL;

    sqlite3_open(":memory:", &db);
    int rc = sqlite3_exec(db, "CREATE VIRTUAL TABLE t USING fts5(a, b)", NULL, NULL, &errmsg);
    if (rc != 0) {
        printf("Error: %s\n", errmsg);
        sqlite3_free(errmsg);
    } else {
        printf("fts5 works!\n");
    }
    sqlite3_close(db);
}
*/
import "C"

func main() {
    C.test_sqlite()
}
EOF
cd /tmp/sqlitetest && go run main.go 2>&1

