	rc := C.sqlite3_exec(db.handle, csql, nil, nil, &errmsg)
	if rc != C.SQLITE_OK {
		msg := C.GoString(errmsg)
		C.sqlite3_free(unsafe.Pointer(errmsg))
		return fmt.Errorf("sqlite3_exec: %s", msg)
	}
	return nil
}

func (db *DB) Prepare(sql string) (*Stmt, error) {
	csql := C.CString(sql)
	defer C.free(unsafe.Pointer(csql))

	var stmt *C.sqlite3_stmt
	rc := C.sqlite3_prepare_v2(db.handle, csql, -1, &stmt, nil)
	if rc != C.SQLITE_OK {
		errmsg := C.GoString(C.sqlite3_errmsg(db.handle))
		return nil, fmt.Errorf("sqlite3_prepare: %s: %s", sql, errmsg)
	}
