		s.handle = nil
	}
}

func (s *Stmt) Bind(idx int, val interface{}) error {
	i := C.int(idx)
	switch v := val.(type) {
	case nil:
		C.sqlite3_bind_null(s.handle, i)
	case int:
		C.sqlite3_bind_int64(s.handle, i, C.sqlite3_int64(v))
	case int64:
