			if c == quoteChar {
				inQuote = false
			}
			cur.WriteByte(c)
		} else if c == '"' || c == '\'' {
			inQuote = true
			quoteChar = c
			cur.WriteByte(c)
		} else if c == '.' {
			parts = append(parts, cur.String())
			cur.Reset()
		} else {
			cur.WriteByte(c)
		}
	}
	if cur.Len() > 0 {
		parts = append(parts, cur.String())
	}
	return parts
}

func unquoteTOMLKey(key string) string {
	key = strings.TrimSpace(key)
	if len(key) >= 2 {
		if (key[0] == '"' && key[len(key)-1] == '"') ||
			(key[0] == '\'' && key[len(key)-1] == '\'') {
			return key[1 : len(key)-1]
		}
	}
	return key
}

func parseTOMLValue(s string) (TOMLValue, error) {
	s = strings.TrimSpace(s)

	// Strip inline comment (only for non-string values)
	// We need to be careful not to strip comments inside strings

	// Boolean
	if s == "true" {
		return true, nil
	}
	if s == "false" {
		return false, nil
	}

	// String (double quoted)
	if strings.HasPrefix(s, `"`) {
		return parseTOMLString(s)
	}

	// String (single quoted)
	if strings.HasPrefix(s, `'`) {
		end := strings.LastIndex(s, `'`)
		if end > 0 {
			return s[1:end], nil
		}
		return s, nil
	}

	// Multiline string
	if strings.HasPrefix(s, `"""`) {
		return strings.TrimSuffix(strings.TrimPrefix(s, `"""`), `"""`), nil
	}

	// Array
	if strings.HasPrefix(s, "[") {
		return parseTOMLArray(s)
	}

	// Inline table
	if strings.HasPrefix(s, "{") {
		return parseTOMLInlineTable(s)
	}

	// Strip comment for non-string values
	if idx := strings.Index(s, " #"); idx >= 0 {
		s = strings.TrimSpace(s[:idx])
	}

	// Integer or float
	if n, err := strconv.ParseInt(s, 10, 64); err == nil {
		return n, nil
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return f, nil
	}

	// Return as string
	return s, nil
}

func parseTOMLString(s string) (string, error) {
	if !strings.HasPrefix(s, `"`) {
		return s, nil
	}
	// Find the end quote
	var result strings.Builder
	i := 1
	for i < len(s) {
		c := s[i]
		if c == '\\' && i+1 < len(s) {
			i++
			switch s[i] {
			case 'n':
				result.WriteByte('\n')
			case 't':
				result.WriteByte('\t')
			case 'r':
				result.WriteByte('\r')
			case '"':
				result.WriteByte('"')
			case '\\':
				result.WriteByte('\\')
			default:
				result.WriteByte('\\')
				result.WriteByte(s[i])
			}
		} else if c == '"' {
			break
		} else {
			result.WriteByte(c)
		}
		i++
	}
	return result.String(), nil
}

func parseTOMLArray(s string) ([]TOMLValue, error) {
	if !strings.HasPrefix(s, "[") {
		return nil, fmt.Errorf("not an array: %s", s)
	}

	// Find the matching closing bracket
	depth := 0
	end := -1
	for i, c := range s {
		if c == '[' {
			depth++
		} else if c == ']' {
			depth--
			if depth == 0 {
				end = i
				break
			}
		}
	}
	if end < 0 {
		end = len(s) - 1
	}

	inner := strings.TrimSpace(s[1:end])
	if inner == "" {
		return []TOMLValue{}, nil
	}

	// Split by comma (but not inside nested brackets or strings)
	var items []TOMLValue
	var cur strings.Builder
	depth = 0
	inStr := false
	strChar := byte(0)

	for i := 0; i < len(inner); i++ {
		c := inner[i]
		if inStr {
			if c == strChar {
				inStr = false
			}
			cur.WriteByte(c)
		} else if c == '"' || c == '\'' {
			inStr = true
			strChar = c
			cur.WriteByte(c)
		} else if c == '[' || c == '{' {
			depth++
			cur.WriteByte(c)
		} else if c == ']' || c == '}' {
			depth--
			cur.WriteByte(c)
		} else if c == ',' && depth == 0 {
			val, err := parseTOMLValue(strings.TrimSpace(cur.String()))
			if err != nil {
				return nil, err
			}
			items = append(items, val)
			cur.Reset()
		} else {
			cur.WriteByte(c)
		}
	}

	if cur.Len() > 0 {
		trimmed := strings.TrimSpace(cur.String())
		if trimmed != "" {
			val, err := parseTOMLValue(trimmed)
			if err != nil {
				return nil, err
			}
			items = append(items, val)
		}
	}

	return items, nil
}

func parseTOMLInlineTable(s string) (TOMLTable, error) {
	result := make(TOMLTable)
	// Find matching brace
	end := strings.LastIndex(s, "}")
	if end < 0 {
		end = len(s)
	} else {
		end++
	}
	inner := strings.TrimSpace(s[1 : end-1])
	if inner == "" {
		return result, nil
	}

	// Split by comma
	for _, part := range strings.Split(inner, ",") {
		part = strings.TrimSpace(part)
		eqIdx := strings.IndexByte(part, '=')
		if eqIdx < 0 {
			continue
		}
		k := strings.TrimSpace(part[:eqIdx])
		v, err := parseTOMLValue(strings.TrimSpace(part[eqIdx+1:]))
		if err != nil {
			continue
		}
		result[k] = v
	}
	return result, nil
}

// GetString retrieves a string value from a TOMLTable
func (t TOMLTable) GetString(key string, def string) string {
	if v, ok := t[key]; ok {
		if s, ok := v.(string); ok {
			return s
		}
	}
	return def
}

// GetBool retrieves a bool value from a TOMLTable
func (t TOMLTable) GetBool(key string, def bool) bool {
	if v, ok := t[key]; ok {
		if b, ok := v.(bool); ok {
			return b
		}
	}
	return def
}

// GetInt retrieves an int64 value from a TOMLTable
func (t TOMLTable) GetInt(key string, def int64) int64 {
	if v, ok := t[key]; ok {
		switch n := v.(type) {
		case int64:
			return n
		case int:
			return int64(n)
		}
	}
	return def
}

// GetTable retrieves a nested TOMLTable
func (t TOMLTable) GetTable(key string) TOMLTable {
	if v, ok := t[key]; ok {
		if tbl, ok := v.(TOMLTable); ok {
			return tbl
		}
	}
	return nil
}

// GetStringSlice retrieves a string slice value
func (t TOMLTable) GetStringSlice(key string) []string {
	if v, ok := t[key]; ok {
		if arr, ok := v.([]TOMLValue); ok {
			var result []string
			for _, item := range arr {
				if s, ok := item.(string); ok {
					result = append(result, s)
				}
			}
			return result
		}
		if s, ok := v.(string); ok {
			return []string{s}
		}
	}
	return nil
}
