			ColonTags:     false,
			MultiwordTags: false,
		},
		Tool:    ToolConfig{},
		Filters: make(map[string]string),
		Aliases: make(map[string]string),
	}
}

func LoadConfig(notebookDir string) (Config, error) {
	cfg := DefaultConfig()
	configPath := filepath.Join(notebookDir, ".zk", "config.toml")

	data, err := os.ReadFile(configPath)
	if err != nil {
		if os.IsNotExist(err) {
			return cfg, nil
		}
		return cfg, err
	}

	tbl, err := ParseTOML(string(data))
	if err != nil {
		return cfg, fmt.Errorf("parse config: %v", err)
	}

	// Parse [note] section
	if note := tbl.GetTable("note"); note != nil {
		cfg.Note.Language = note.GetString("language", cfg.Note.Language)
		cfg.Note.DefaultTitle = note.GetString("default-title", cfg.Note.DefaultTitle)
		cfg.Note.Filename = note.GetString("filename", cfg.Note.Filename)
		cfg.Note.Extension = note.GetString("extension", cfg.Note.Extension)
		cfg.Note.Template = note.GetString("template", cfg.Note.Template)
		cfg.Note.Exclude = note.GetStringSlice("exclude")
		cfg.Note.IDCharset = note.GetString("id-charset", cfg.Note.IDCharset)
		if n := note.GetInt("id-length", 0); n > 0 {
			cfg.Note.IDLength = int(n)
		}
		cfg.Note.IDCase = note.GetString("id-case", cfg.Note.IDCase)
	}

	// Parse [extra] section
	if extra := tbl.GetTable("extra"); extra != nil {
		for k, v := range extra {
			if s, ok := v.(string); ok {
				cfg.Extra[k] = s
			}
		}
	}

	// Parse [format.markdown] section
	if format := tbl.GetTable("format"); format != nil {
		if md := format.GetTable("markdown"); md != nil {
			cfg.Markdown.LinkFormat = md.GetString("link-format", cfg.Markdown.LinkFormat)
			if v, ok := md["link-encode-path"]; ok {
				if b, ok := v.(bool); ok {
					cfg.Markdown.LinkEncodePath = &b
				}
			}
			if v, ok := md["link-drop-extension"]; ok {
				if b, ok := v.(bool); ok {
					cfg.Markdown.LinkDropExt = &b
				}
			}
			if v, ok := md["hashtags"]; ok {
				if b, ok := v.(bool); ok {
					cfg.Markdown.Hashtags = b
				}
			}
			if v, ok := md["colon-tags"]; ok {
				if b, ok := v.(bool); ok {
					cfg.Markdown.ColonTags = b
				}
			}
			if v, ok := md["multiword-tags"]; ok {
				if b, ok := v.(bool); ok {
					cfg.Markdown.MultiwordTags = b
				}
			}
		}
	}

	// Parse [tool] section
	if tool := tbl.GetTable("tool"); tool != nil {
		cfg.Tool.Editor = tool.GetString("editor", "")
		cfg.Tool.Pager = tool.GetString("pager", "")
		cfg.Tool.FzfPreview = tool.GetString("fzf-preview", "")
	}

	// Parse [filter] section
	if filters := tbl.GetTable("filter"); filters != nil {
		for k, v := range filters {
			if s, ok := v.(string); ok {
				cfg.Filters[k] = s
			}
		}
	}

	// Parse [alias] section
	if aliases := tbl.GetTable("alias"); aliases != nil {
		for k, v := range aliases {
			if s, ok := v.(string); ok {
				cfg.Aliases[k] = s
			}
		}
	}

	// Parse [group."name"] sections
	if groups := tbl.GetTable("group"); groups != nil {
		for name, v := range groups {
			if grpTbl, ok := v.(TOMLTable); ok {
				grp := GroupConfig{
					Note:  cfg.Note, // inherit defaults
					Extra: make(map[string]string),
				}
				grp.Paths = grpTbl.GetStringSlice("paths")
				if len(grp.Paths) == 0 {
					grp.Paths = []string{name}
				}

				if noteTbl := grpTbl.GetTable("note"); noteTbl != nil {
					grp.Note.Language = noteTbl.GetString("language", grp.Note.Language)
					grp.Note.DefaultTitle = noteTbl.GetString("default-title", grp.Note.DefaultTitle)
					grp.Note.Filename = noteTbl.GetString("filename", grp.Note.Filename)
					grp.Note.Extension = noteTbl.GetString("extension", grp.Note.Extension)
					grp.Note.Template = noteTbl.GetString("template", grp.Note.Template)
					grp.Note.IDCharset = noteTbl.GetString("id-charset", grp.Note.IDCharset)
					if n := noteTbl.GetInt("id-length", 0); n > 0 {
						grp.Note.IDLength = int(n)
					}
					grp.Note.IDCase = noteTbl.GetString("id-case", grp.Note.IDCase)
				}

				if extraTbl := grpTbl.GetTable("extra"); extraTbl != nil {
					for k, v := range extraTbl {
						if s, ok := v.(string); ok {
							grp.Extra[k] = s
						}
					}
				}

				cfg.Groups[name] = grp
			}
		}
	}

	// Parse [lsp] section
	if lsp := tbl.GetTable("lsp"); lsp != nil {
		cfg.LSP.Diagnostics = make(map[string]interface{})
		cfg.LSP.Completion = make(map[string]string)

		if diag := lsp.GetTable("diagnostics"); diag != nil {
			for k, v := range diag {
				cfg.LSP.Diagnostics[k] = v
			}
		}
		if comp := lsp.GetTable("completion"); comp != nil {
			for k, v := range comp {
				if s, ok := v.(string); ok {
					cfg.LSP.Completion[k] = s
				}
			}
		}
	}

	return cfg, nil
}

// FindGroupForPath finds which group configuration to use for a given directory path
// relative to the notebook root
func (cfg *Config) FindGroupForPath(relDir string) *GroupConfig {
	relDir = strings.TrimSuffix(relDir, "/")
	for name, grp := range cfg.Groups {
		for _, path := range grp.Paths {
			path = strings.TrimSuffix(path, "/")
			if relDir == path || strings.HasPrefix(relDir, path+"/") {
				g := grp
				_ = name
				return &g
			}
		}
	}
	return nil
}

// NoteConfigForPath returns the NoteConfig to use for the given path
func (cfg *Config) NoteConfigForPath(relDir string) NoteConfig {
	if grp := cfg.FindGroupForPath(relDir); grp != nil {
		return grp.Note
	}
	return cfg.Note
}

// ExtraForPath returns the extra variables to use for the given path
func (cfg *Config) ExtraForPath(relDir string) map[string]string {
	base := make(map[string]string)
	for k, v := range cfg.Extra {
		base[k] = v
	}
	if grp := cfg.FindGroupForPath(relDir); grp != nil {
		for k, v := range grp.Extra {
			base[k] = v
		}
	}
	return base
}

// DefaultNoteConfig generates default config.toml content for the init command
