func LoadConfig(notebookDir string) (Config, error) {
	cfg := DefaultConfig()
	configPath := filepath.Join(notebookDir, ".zk", "config.toml")

	data, err := os.ReadFile(configPath)
	if err != nil {
		if os.IsNotExist(err) {
			return cfg, nil
		}
		return cfg, err
	}

	tbl, err := ParseTOML(string(data))
	if err != nil {
		return cfg, fmt.Errorf("parse config: %v", err)
	}

	// Parse [note] section
	if note := tbl.GetTable("note"); note != nil {
		cfg.Note.Language = note.GetString("language", cfg.Note.Language)
		cfg.Note.DefaultTitle = note.GetString("default-title", cfg.Note.DefaultTitle)
		cfg.Note.Filename = note.GetString("filename", cfg.Note.Filename)
		cfg.Note.Extension = note.GetString("extension", cfg.Note.Extension)
		cfg.Note.Template = note.GetString("template", cfg.Note.Template)
		cfg.Note.Exclude = note.GetStringSlice("exclude")
		cfg.Note.IDCharset = note.GetString("id-charset", cfg.Note.IDCharset)
		if n := note.GetInt("id-length", 0); n > 0 {
			cfg.Note.IDLength = int(n)
		}
		cfg.Note.IDCase = note.GetString("id-case", cfg.Note.IDCase)
	}

	// Parse [extra] section
	if extra := tbl.GetTable("extra"); extra != nil {
		for k, v := range extra {
			if s, ok := v.(string); ok {
				cfg.Extra[k] = s
			}
		}
	}

	// Parse [format.markdown] section
	if format := tbl.GetTable("format"); format != nil {
		if md := format.GetTable("markdown"); md != nil {
			cfg.Markdown.LinkFormat = md.GetString("link-format", cfg.Markdown.LinkFormat)
			if v, ok := md["link-encode-path"]; ok {
				if b, ok := v.(bool); ok {
					cfg.Markdown.LinkEncodePath = &b
				}
			}
			if v, ok := md["link-drop-extension"]; ok {
				if b, ok := v.(bool); ok {
					cfg.Markdown.LinkDropExt = &b
				}
			}
			if v, ok := md["hashtags"]; ok {
				if b, ok := v.(bool); ok {
					cfg.Markdown.Hashtags = b
				}
			}
			if v, ok := md["colon-tags"]; ok {
				if b, ok := v.(bool); ok {
					cfg.Markdown.ColonTags = b
				}
			}
			if v, ok := md["multiword-tags"]; ok {
				if b, ok := v.(bool); ok {
					cfg.Markdown.MultiwordTags = b
				}
			}
		}
	}

	// Parse [tool] section
	if tool := tbl.GetTable("tool"); tool != nil {
		cfg.Tool.Editor = tool.GetString("editor", "")
		cfg.Tool.Pager = tool.GetString("pager", "")
		cfg.Tool.FzfPreview = tool.GetString("fzf-preview", "")
	}

	// Parse [filter] section
	if filters := tbl.GetTable("filter"); filters != nil {
		for k, v := range filters {
			if s, ok := v.(string); ok {
				cfg.Filters[k] = s
			}
		}
	}

	// Parse [alias] section
	if aliases := tbl.GetTable("alias"); aliases != nil {
		for k, v := range aliases {
			if s, ok := v.(string); ok {
				cfg.Aliases[k] = s
			}
		}
	}

	// Parse [group."name"] sections
	if groups := tbl.GetTable("group"); groups != nil {
		for name, v := range groups {
			if grpTbl, ok := v.(TOMLTable); ok {
				grp := GroupConfig{
					Note:  cfg.Note, // inherit defaults
					Extra: make(map[string]string),
				}
				grp.Paths = grpTbl.GetStringSlice("paths")
				if len(grp.Paths) == 0 {
					grp.Paths = []string{name}
				}

				if noteTbl := grpTbl.GetTable("note"); noteTbl != nil {
