# Now let me write the template engine (Handlebars-like)
cat > /workspace/zk-impl/internal/template.go << 'GOEOF'
package internal

import (
	"fmt"
	"os/exec"
	"regexp"
	"strings"
	"time"
	"unicode"
)

// TemplateContext holds template variables
type TemplateContext map[string]interface{}

// RenderTemplate renders a Handlebars-like template with the given context
func RenderTemplate(template string, ctx TemplateContext) (string, error) {
	var result strings.Builder
	i := 0
	for i < len(template) {
		if i+1 < len(template) && template[i] == '{' && template[i+1] == '{' {
			// Find closing }}
			end := strings.Index(template[i+2:], "}}")
			if end < 0 {
				result.WriteString(template[i:])
				break
			}
			expr := strings.TrimSpace(template[i+2 : i+2+end])
			val, err := evalTemplateExpr(expr, ctx)
			if err != nil {
				return "", fmt.Errorf("template expression %q: %v", expr, err)
			}
			result.WriteString(val)
			i = i + 2 + end + 2
		} else {
			result.WriteByte(template[i])
			i++
		}
	}
	return result.String(), nil
}

// evalTemplateExpr evaluates a single template expression
func evalTemplateExpr(expr string, ctx TemplateContext) (string, error) {
	expr = strings.TrimSpace(expr)

	// Handle function calls like: slug title, format-date now "%Y-%m-%d", etc.
	parts := parseExprParts(expr)
	if len(parts) == 0 {
		return "", nil
	}

	if len(parts) == 1 {
		return evalTemplateVar(parts[0], ctx)
	}

	// Function call
	fnName := parts[0]
	args := parts[1:]
	return callTemplateFunc(fnName, args, ctx)
}

// parseExprParts splits an expression into function name and arguments
// respecting quoted strings
func parseExprParts(expr string) []string {
	var parts []string
	var cur strings.Builder
	inSingle := false
	inDouble := false

	for i := 0; i < len(expr); i++ {
		c := expr[i]
		if inSingle {
			if c == '\'' {
				inSingle = false
				cur.WriteByte(c)
			} else {
				cur.WriteByte(c)
			}
		} else if inDouble {
			if c == '"' {
				inDouble = false
				cur.WriteByte(c)
			} else {
				cur.WriteByte(c)
			}
		} else if c == '\'' {
			inSingle = true
			cur.WriteByte(c)
		} else if c == '"' {
			inDouble = true
			cur.WriteByte(c)
		} else if c == ' ' || c == '\t' {
			if cur.Len() > 0 {
				parts = append(parts, cur.String())
				cur.Reset()
			}
		} else {
			cur.WriteByte(c)
		}
	}
	if cur.Len() > 0 {
		parts = append(parts, cur.String())
	}
	return parts
}

// evalTemplateVar evaluates a variable reference (possibly dotted)
func evalTemplateVar(name string, ctx TemplateContext) (string, error) {
	// Handle dotted access like extra.key
	parts := strings.SplitN(name, ".", 2)
	if len(parts) == 2 {
		parent, ok := ctx[parts[0]]
		if !ok {
			return "", nil
		}
		if m, ok := parent.(map[string]string); ok {
			return m[parts[1]], nil
		}
		if m, ok := parent.(map[string]interface{}); ok {
			if v, ok := m[parts[1]]; ok {
				return fmt.Sprintf("%v", v), nil
			}
		}
		return "", nil
	}

	v, ok := ctx[name]
	if !ok {
		return "", nil
	}
	return formatValue(v), nil
}

func formatValue(v interface{}) string {
	if v == nil {
		return ""
	}
	switch val := v.(type) {
	case string:
		return val
	case bool:
		if val {
			return "true"
		}
		return "false"
	case int:
		return fmt.Sprintf("%d", val)
	case int64:
		return fmt.Sprintf("%d", val)
	case float64:
		return fmt.Sprintf("%g", val)
	case time.Time:
		return val.Format("2006-01-02 15:04:05.999999999 -0700 MST")
	case []string:
		return strings.Join(val, "")
	default:
		return fmt.Sprintf("%v", v)
	}
}

// resolveArg resolves a template argument (either a literal string or variable reference)
func resolveArg(arg string, ctx TemplateContext) string {
	// Quoted string literal
	if len(arg) >= 2 {
		if (arg[0] == '"' && arg[len(arg)-1] == '"') ||
			(arg[0] == '\'' && arg[len(arg)-1] == '\'') {
			return arg[1 : len(arg)-1]
		}
	}
	// Variable reference
	v, _ := evalTemplateVar(arg, ctx)
	return v
}

// callTemplateFunc calls a template function
func callTemplateFunc(name string, args []string, ctx TemplateContext) (string, error) {
	switch name {
	case "format-date":
		return templateFuncFormatDate(args, ctx)
	case "slug":
		s := resolveArg(args[0], ctx)
		return slugify(s), nil
	case "lower":
		if len(args) == 0 {
			return "", nil
		}
		return strings.ToLower(resolveArg(args[0], ctx)), nil
	case "upper":
		if len(args) == 0 {
			return "", nil
		}
		return strings.ToUpper(resolveArg(args[0], ctx)), nil
	case "trim":
		if len(args) == 0 {
			return "", nil
		}
		return strings.TrimSpace(resolveArg(args[0], ctx)), nil
	case "prepend":
		if len(args) < 2 {
			return "", nil
		}
		prefix := resolveArg(args[0], ctx)
		s := resolveArg(args[1], ctx)
		return prefix + s, nil
	case "append":
