package internal

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"regexp"
	"strings"
	"unicode"
)

// Note represents a parsed note
type ParsedNote struct {
	Path       string
	Title      string
	Lead       string
	Body       string
	RawContent string
	WordCount  int
	Metadata   map[string]interface{}
	Tags       []string
	Links      []ParsedLink
}

// ParsedLink represents a link found in a note
type ParsedLink struct {
	Title    string
	Href     string
	Type     string // "wiki-link", "markdown", or custom
	External bool
	Rels     []string
	Snippet  string
	SnippetStart int
	SnippetEnd   int
}

// MarkdownParser parses markdown notes
type MarkdownParser struct {
	Config MarkdownConfig
}

// NoteChecksum computes the SHA256 checksum of a note's content
func NoteChecksum(content string) string {
	h := sha256.Sum256([]byte(content))
	return hex.EncodeToString(h[:])
}

// ParseNote parses a markdown note file
func (p *MarkdownParser) ParseNote(content string) *ParsedNote {
	note := &ParsedNote{
		RawContent: content,
		Metadata:   make(map[string]interface{}),
	}

	// Parse YAML frontmatter
	body := content
	if strings.HasPrefix(content, "---\n") || strings.HasPrefix(content, "---\r\n") {
		endIdx := strings.Index(content[4:], "\n---")
		if endIdx >= 0 {
			frontmatter := content[4 : 4+endIdx]
			body = content[4+endIdx+4:]
			if len(body) > 0 && body[0] == '\n' {
				body = body[1:]
			} else if len(body) > 1 && body[0] == '\r' && body[1] == '\n' {
				body = body[2:]
			}
			p.parseFrontmatter(frontmatter, note)
		}
	}

	// Extract title from body if not set by frontmatter
	if note.Title == "" {
		note.Title = extractTitle(body)
	}

	// Set body (without frontmatter)
	note.Body = strings.TrimRight(body, "\n\r")

	// Extract lead (first paragraph)
	note.Lead = extractLead(body)

	// Count words in body
	note.WordCount = countWords(content)

	// Extract hashtags if enabled
	if p.Config.Hashtags {
		tags := extractHashtags(body, p.Config.MultiwordTags)
		for _, tag := range tags {
			if !containsString(note.Tags, tag) {
				note.Tags = append(note.Tags, tag)
			}
		}
	}

	// Extract colon tags if enabled
	if p.Config.ColonTags {
		tags := extractColonTags(body)
		for _, tag := range tags {
			if !containsString(note.Tags, tag) {
				note.Tags = append(note.Tags, tag)
			}
		}
	}

	// Extract links
	note.Links = p.extractLinks(content)

	return note
}

func containsString(ss []string, s string) bool {
	for _, v := range ss {
		if v == s {
			return true
		}
	}
	return false
}

// parseFrontmatter parses YAML frontmatter
func (p *MarkdownParser) parseFrontmatter(frontmatter string, note *ParsedNote) {
	// Simple YAML parser for common patterns
	lines := strings.Split(frontmatter, "\n")
	var currentKey string
	var inArray bool
	var arrayValues []string
	var sb strings.Builder

	for _, line := range lines {
		line = strings.TrimRight(line, "\r")

		if inArray {
			trimmed := strings.TrimSpace(line)
			if strings.HasPrefix(trimmed, "- ") {
				val := strings.TrimPrefix(trimmed, "- ")
				val = strings.Trim(val, `"'`)
				arrayValues = append(arrayValues, val)
				continue
			} else if trimmed == "" || !strings.HasPrefix(trimmed, " ") {
				// End of array
				note.Metadata[currentKey] = arrayValues
				if currentKey == "tags" {
					note.Tags = append(note.Tags, arrayValues...)
				}
				arrayValues = nil
				inArray = false
				currentKey = ""
			}
		}

		// Key: value
		colonIdx := strings.IndexByte(line, ':')
		if colonIdx < 0 {
			continue
		}
		key := strings.TrimSpace(line[:colonIdx])
		if key == "" || strings.HasPrefix(key, " ") || strings.HasPrefix(key, "\t") {
			continue
		}
		value := strings.TrimSpace(line[colonIdx+1:])

		// Check for inline array
		if strings.HasPrefix(value, "[") {
			// Parse inline array
			innerArr := strings.TrimPrefix(value, "[")
			innerArr = strings.TrimSuffix(innerArr, "]")
			items := splitCSV(innerArr)
			var cleanItems []string
			for _, item := range items {
				item = strings.TrimSpace(item)
				item = strings.Trim(item, `"'`)
				if item != "" {
					cleanItems = append(cleanItems, item)
				}
			}
			note.Metadata[key] = cleanItems
			if key == "tags" {
				note.Tags = append(note.Tags, cleanItems...)
			}
			continue
		}

		// Check for array start (no value)
		if value == "" {
			// Next lines might be array items
			inArray = true
			currentKey = key
			arrayValues = nil
			continue
		}

		// Check for multiline string
		if value == "|" || value == ">" {
			_ = sb.String()
			sb.Reset()
			continue
		}

		// Clean up quoted strings
		cleanVal := value
		if len(cleanVal) >= 2 {
			if (cleanVal[0] == '"' && cleanVal[len(cleanVal)-1] == '"') ||
				(cleanVal[0] == '\'' && cleanVal[len(cleanVal)-1] == '\'') {
				cleanVal = cleanVal[1 : len(cleanVal)-1]
			}
		}

		note.Metadata[key] = cleanVal

		switch key {
		case "title":
			note.Title = cleanVal
		case "tags":
			// Single tag as string
			if cleanVal != "" {
				note.Tags = append(note.Tags, cleanVal)
			}
		}
	}

	// End any pending array
	if inArray && len(arrayValues) > 0 {
		note.Metadata[currentKey] = arrayValues
		if currentKey == "tags" {
			note.Tags = append(note.Tags, arrayValues...)
		}
	}
}

func splitCSV(s string) []string {
	var items []string
	var cur strings.Builder
	inQuote := false
	quoteChar := byte(0)
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inQuote {
			if c == quoteChar {
				inQuote = false
			}
			cur.WriteByte(c)
		} else if c == '"' || c == '\'' {
			inQuote = true
			quoteChar = c
			cur.WriteByte(c)
		} else if c == ',' {
			items = append(items, cur.String())
			cur.Reset()
		} else {
			cur.WriteByte(c)
		}
	}
	if cur.Len() > 0 {
		items = append(items, cur.String())
	}
	return items
}

