func extractHashtags(content string, multiWord bool) []string {
	var tags []string
	seen := make(map[string]bool)

	if multiWord {
		// Extract multi-word tags first #tag words here#
		matches := hashtagMultiWordRe.FindAllStringSubmatch(content, -1)
		for _, m := range matches {
			tag := strings.TrimSpace(m[1])
			if tag != "" && !seen[tag] {
				seen[tag] = true
				tags = append(tags, tag)
			}
		}
	}

	// Extract regular hashtags
	matches := hashtagRe.FindAllStringSubmatch(content, -1)
	for _, m := range matches {
		tag := strings.TrimRight(m[1], ".,;:!?")
		// Validate: must start with letter
		if tag == "" {
			continue
		}
		if !unicode.IsLetter(rune(tag[0])) {
			continue
		}
		if !seen[tag] {
			seen[tag] = true
			tags = append(tags, tag)
		}
	}

	return tags
}

