var colonTagRe = regexp.MustCompile(`:([a-zA-Z][a-zA-Z0-9_-]*(?::[a-zA-Z][a-zA-Z0-9_-]*)+):`)

func extractColonTags(content string) []string {
	var tags []string
	seen := make(map[string]bool)
	matches := colonTagRe.FindAllStringSubmatch(content, -1)
	for _, m := range matches {
		// Split compound tag into individual tags
		parts := strings.Split(m[1], ":")
		for _, p := range parts {
			if p != "" && !seen[p] {
