var mdLinkRe = regexp.MustCompile(`\[([^\]]*)\]\(([^)]+)\)`)

func (p *MarkdownParser) extractLinks(content string) []ParsedLink {
	var links []ParsedLink

	// Extract wiki-links [[target]] or [[target|title]]
	wikiMatches := wikiLinkRe.FindAllStringSubmatchIndex(content, -1)
	for _, loc := range wikiMatches {
		full := content[loc[0]:loc[1]]
		href := content[loc[2]:loc[3]]
		title := href // default title is the href

		// Get the paragraph containing this link
		snippet, start, end := extractSnippet(content, loc[0], loc[1])

		links = append(links, ParsedLink{
			Title:        title,
			Href:         strings.TrimSpace(href),
			Type:         "wiki-link",
			External:     false,
			Snippet:      snippet,
			SnippetStart: start,
			SnippetEnd:   end,
		})
		_ = full
	}

	// Extract markdown links [title](href)
	mdMatches := mdLinkRe.FindAllStringSubmatchIndex(content, -1)
	for _, loc := range mdMatches {
		title := content[loc[2]:loc[3]]
		href := content[loc[4]:loc[5]]

		isExternal := isExternalURL(href)

		snippet, start, end := extractSnippet(content, loc[0], loc[1])

		links = append(links, ParsedLink{
			Title:        title,
			Href:         href,
			Type:         "markdown",
			External:     isExternal,
			Snippet:      snippet,
			SnippetStart: start,
			SnippetEnd:   end,
		})
	}

	return links
}

func isExternalURL(href string) bool {
	return strings.HasPrefix(href, "http://") ||
		strings.HasPrefix(href, "https://") ||
		strings.HasPrefix(href, "ftp://") ||
		strings.HasPrefix(href, "mailto:")
}

// extractSnippet extracts the paragraph/sentence context around a link
func extractSnippet(content string, start, end int) (string, int, int) {
	// Find the start of the paragraph (previous double newline or start of content)
	paragraphStart := 0
	for i := start - 1; i >= 0; i-- {
		if i > 0 && content[i] == '\n' && content[i-1] == '\n' {
			paragraphStart = i + 1
			break
		}
	}

	// Find the end of the paragraph (next double newline or end of content)
	paragraphEnd := len(content)
	for i := end; i < len(content)-1; i++ {
		if content[i] == '\n' && content[i+1] == '\n' {
			paragraphEnd = i
			break
		}
	}

	snippet := content[paragraphStart:paragraphEnd]
	snippet = strings.TrimRight(snippet, "\n\r")
	return snippet, paragraphStart, paragraphEnd
}

// MetadataJSON converts metadata to JSON string
func MetadataJSON(meta map[string]interface{}) string {
	if len(meta) == 0 {
		return "{}"
	}
	b, err := json.Marshal(meta)
	if err != nil {
		return "{}"
	}
	return string(b)
}

// ResolveWikiLink resolves a wiki-link href to a note path
// Returns the path relative to the notebook root, or empty string if not found
func ResolveWikiLink(href string, notePaths []string) string {
	// Try exact match first (without extension)
	for _, path := range notePaths {
		stem := strings.TrimSuffix(path, ".md")
		stem = strings.TrimSuffix(stem, ".markdown")
		// Check if the href matches the stem or filename
		if stem == href || path == href {
			return path
		}
		// Check just the filename stem (basename)
		lastSlash := strings.LastIndex(stem, "/")
		if lastSlash >= 0 {
			if stem[lastSlash+1:] == href {
				return path
			}
		}
	}
	return ""
}

// FormatNoteLink generates a link for a note
func FormatNoteLink(path string, cfg *MarkdownConfig) string {
	stem := strings.TrimSuffix(path, ".md")
	stem = strings.TrimSuffix(stem, ".markdown")

	// Just use the filename stem (basename)
	lastSlash := strings.LastIndex(stem, "/")
	if lastSlash >= 0 {
		stem = stem[lastSlash+1:]
	}

	if cfg.LinkFormat == "wiki" {
		return fmt.Sprintf("[[%s]]", stem)
	}
	// Markdown format
	return fmt.Sprintf("[%s](%s)", stem, path)
}

