// GenerateID generates a random ID with the given charset, length, and case
func GenerateID(charset string, length int, idCase string) string {
	var chars []rune
	switch charset {
	case "letters":
		chars = []rune("abcdefghijklmnopqrstuvwxyz")
	case "numbers":
		chars = []rune("0123456789")
	case "alphanum":
		chars = []rune("abcdefghijklmnopqrstuvwxyz0123456789")
	case "hex":
		chars = []rune("0123456789abcdef")
	default:
		// Custom charset
		chars = []rune(charset)
	}

	result := make([]rune, length)
	for i := range result {
		result[i] = chars[rand.Intn(len(chars))]
	}

	s := string(result)
	switch idCase {
	case "upper":
		s = strings.ToUpper(s)
	case "lower":
		s = strings.ToLower(s)
	// "mixed" stays as is
	}
	return s
}

// IsIDUnique checks if an ID is unique in the notebook
func (nb *Notebook) IsIDUnique(id string, extension string) bool {
	path := id + "." + extension
	_, err := os.Stat(filepath.Join(nb.RootDir, path))
	return os.IsNotExist(err)
}

// GenerateUniqueID generates a unique ID for a new note
func (nb *Notebook) GenerateUniqueID(noteCfg NoteConfig) string {
	for {
		id := GenerateID(noteCfg.IDCharset, noteCfg.IDLength, noteCfg.IDCase)
		if nb.IsIDUnique(id, noteCfg.Extension) {
			return id
		}
	}
}

