func (nb *Notebook) TemplateDir() string {
	return filepath.Join(nb.RootDir, ".zk", "templates")
}

// LoadTemplate loads a template file
func (nb *Notebook) LoadTemplate(name string) (string, error) {
	// If absolute path or ~ path
	if strings.HasPrefix(name, "/") || strings.HasPrefix(name, "~/") {
		if strings.HasPrefix(name, "~/") {
			home, _ := os.UserHomeDir()
			name = filepath.Join(home, name[2:])
		}
		data, err := os.ReadFile(name)
		if err != nil {
			return "", err
		}
		return string(data), nil
	}

	// Relative to templates dir
	tmplPath := filepath.Join(nb.TemplateDir(), name)
	data, err := os.ReadFile(tmplPath)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

// RelPath returns the path relative to the notebook root
func (nb *Notebook) RelPath(absPath string) string {
	rel, err := filepath.Rel(nb.RootDir, absPath)
	if err != nil {
		return absPath
	}
	return filepath.ToSlash(rel)
}

// SortablePath creates a sortable version of a path
// Used for consistent directory-then-file ordering
func SortablePath(path string) string {
	// Replace path separators to sort directories together
	return strings.ToLower(path)
}

// ParseRelativeDate parses natural language date expressions like "last two weeks"
func ParseRelativeDate(expr string) (time.Time, error) {
	now := time.Now()
	expr = strings.TrimSpace(strings.ToLower(expr))

	// Parse simple date like "2023-01-15"
	if t, err := time.Parse("2006-01-02", expr); err == nil {
		return t, nil
	}

	// Parse relative expressions
	switch expr {
	case "today":
		return time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, now.Location()), nil
	case "yesterday":
		d := now.AddDate(0, 0, -1)
		return time.Date(d.Year(), d.Month(), d.Day(), 0, 0, 0, 0, d.Location()), nil
	case "tomorrow":
		d := now.AddDate(0, 0, 1)
		return time.Date(d.Year(), d.Month(), d.Day(), 0, 0, 0, 0, d.Location()), nil
	}

	// Parse "last N weeks/days/months"
	var amount int
	var unit string
	if _, err := fmt.Sscanf(expr, "last %d %s", &amount, &unit); err == nil {
		return subtractDuration(now, amount, unit), nil
	}
	if _, err := fmt.Sscanf(expr, "%d %s ago", &amount, &unit); err == nil {
		return subtractDuration(now, amount, unit), nil
	}

	return time.Time{}, fmt.Errorf("cannot parse date: %q", expr)
}

func subtractDuration(t time.Time, amount int, unit string) time.Time {
	unit = strings.TrimSuffix(unit, "s") // pluralization
	switch unit {
	case "day", "d":
		return t.AddDate(0, 0, -amount)
	case "week", "w":
		return t.AddDate(0, 0, -amount*7)
	case "month":
		return t.AddDate(0, -amount, 0)
	case "year", "y":
		return t.AddDate(-amount, 0, 0)
	}
	return t
}
