func migrateDB(db *DB) error {
	// Check if migrations table exists
	row, err := db.QueryRow("SELECT name FROM sqlite_master WHERE type='table' AND name='migrations'")
	if err != nil {
		return err
	}

	var version int64 = 0
	if row == nil {
		// Create migrations table
		if err := db.ExecRaw("CREATE TABLE IF NOT EXISTS migrations (version INTEGER NOT NULL)"); err != nil {
			return fmt.Errorf("create migrations table: %v", err)
		}
		if err := db.ExecRaw("INSERT INTO migrations VALUES (0)"); err != nil {
			return fmt.Errorf("insert initial migration: %v", err)
		}
	} else {
		r, err := db.QueryRow("SELECT version FROM migrations")
		if err != nil {
			return err
		}
		if r != nil {
			version = r["version"].(int64)
		}
	}

	// Run migrations in sequence
	migrations := []struct {
		version int64
		up      func(*DB) error
	}{
		{1, migration01},
		{2, migration02},
		{3, migration03},
		{4, migration04},
		{5, migration05},
		{6, migration06},
		{7, migration07},
		{8, migration08},
		{9, migration09},
	}

	for _, m := range migrations {
		if version < m.version {
			if err := m.up(db); err != nil {
				return fmt.Errorf("database migration failed: %v", err)
			}
			if err := db.Exec("UPDATE migrations SET version = ?", m.version); err != nil {
				return fmt.Errorf("update migration version: %v", err)
			}
			version = m.version
		}
	}

	return nil
}

