package internal

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// IndexStats contains statistics from an indexing operation
type IndexStats struct {
	Added    int
	Modified int
	Removed  int
	Unchanged int
}

// IndexNote represents a note being indexed
type IndexNote struct {
	ID          int64
	Path        string
	Title       string
	Lead        string
	Body        string
	RawContent  string
	WordCount   int
	Metadata    string
	Checksum    string
	Created     time.Time
	Modified    time.Time
}

// IndexOptions contains options for the indexing operation
type IndexOptions struct {
	Force   bool
	Verbose bool
	Quiet   bool
}

// IndexNotebook indexes all notes in the notebook
func (nb *Notebook) IndexNotebook(opts IndexOptions) (IndexStats, error) {
	var stats IndexStats

	// Set reindexing flag
	if err := nb.setMetadata("zk.reindexing_required", "false"); err != nil {
		return stats, fmt.Errorf("indexing failed: failed to get metadata with key zk.reindexing_required: database query: %s", err)
	}

	// Get all existing notes from DB
	existing, err := nb.getExistingNotes()
	if err != nil {
		return stats, fmt.Errorf("indexing failed: %v", err)
	}

	// Walk the notebook directory to find all markdown files
	var noteFiles []string
	err = filepath.Walk(nb.RootDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if info.IsDir() {
			// Skip .zk directory
			if filepath.Base(path) == ".zk" {
				return filepath.SkipDir
			}
			return nil
		}
		// Check if it's a markdown file
		ext := strings.ToLower(filepath.Ext(path))
		if ext != ".md" && ext != ".markdown" {
			return nil
		}
		// Check exclude patterns
		relPath := nb.RelPath(path)
		if nb.isExcluded(relPath) {
			return nil
		}
		noteFiles = append(noteFiles, path)
		return nil
	})
	if err != nil {
		return stats, fmt.Errorf("walk directory: %v", err)
	}

	// Process each file
	seenPaths := make(map[string]bool)
	parser := &MarkdownParser{Config: nb.Config.Markdown}

	for _, filePath := range noteFiles {
		relPath := nb.RelPath(filePath)
		seenPaths[relPath] = true

		// Read file content
		content, err := os.ReadFile(filePath)
		if err != nil {
			fmt.Fprintf(os.Stderr, "zk: warning: %s: cannot read file: %v\n", relPath, err)
			continue
		}
		contentStr := string(content)

		// Get file modification time
		fileInfo, err := os.Stat(filePath)
		if err != nil {
			continue
		}
		modTime := fileInfo.ModTime()

		// Compute checksum
		checksum := NoteChecksum(contentStr)

		// Check if note exists in DB
		if existingNote, ok := existing[relPath]; ok {
			if !opts.Force && existingNote.Checksum == checksum {
				if opts.Verbose {
					fmt.Printf("- unchanged %s\n", relPath)
				}
				stats.Unchanged++
				continue
			}

			// Parse the note
			parsedNote := parser.ParseNote(contentStr)

			// Update the note in DB
			err = nb.updateNote(existingNote.ID, relPath, parsedNote, existingNote.Created, modTime, checksum)
			if err != nil {
				fmt.Fprintf(os.Stderr, "zk: warning: %s: failed to index the note: %v\n", relPath, err)
				continue
			}

			if opts.Verbose {
				fmt.Printf("~ modified %s\n", relPath)
			}
			stats.Modified++
		} else {
			// Parse the note
			parsedNote := parser.ParseNote(contentStr)

			// Add the note to DB
			err = nb.addNote(relPath, parsedNote, modTime, modTime, checksum)
			if err != nil {
				fmt.Fprintf(os.Stderr, "zk: warning: %s: failed to index the note: %v\n", relPath, err)
				continue
			}

			if opts.Verbose {
				fmt.Printf("+ added %s\n", relPath)
			}
			stats.Added++
		}
	}

	// Remove notes that no longer exist
	for path, note := range existing {
		if !seenPaths[path] {
			if err := nb.removeNote(note.ID); err != nil {
				fmt.Fprintf(os.Stderr, "zk: warning: failed to remove %s: %v\n", path, err)
			} else {
				if opts.Verbose {
					fmt.Printf("- removed %s\n", path)
				}
				stats.Removed++
			}
		}
	}

	return stats, nil
}

// getExistingNotes returns all notes currently in the database
func (nb *Notebook) getExistingNotes() (map[string]*IndexNote, error) {
	rows, err := nb.DB.QueryRows("SELECT id, path, checksum, created, modified FROM notes")
	if err != nil {
		return nil, err
	}

	result := make(map[string]*IndexNote)
	for _, row := range rows {
		note := &IndexNote{}
		note.ID = row["id"].(int64)
		note.Path = row["path"].(string)
		note.Checksum = row["checksum"].(string)
		if v := row["created"]; v != nil {
			note.Created, _ = parseTimeString(v.(string))
		}
		if v := row["modified"]; v != nil {
			note.Modified, _ = parseTimeString(v.(string))
		}
		result[note.Path] = note
	}
	return result, nil
}

// addNote adds a new note to the database
func (nb *Notebook) addNote(relPath string, parsed *ParsedNote, created, modified time.Time, checksum string) error {
	metaJSON := NoteMetadataJSON(parsed.Metadata)
	filename := filepath.Base(relPath)
	sortablePath := SortablePath(relPath)

	err := nb.DB.Exec(`
		INSERT INTO notes (path, sortable_path, filename, title, lead, body, raw_content, word_count, metadata, checksum, created, modified)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
	`,
		relPath,
		sortablePath,
		filename,
		parsed.Title,
		parsed.Lead,
		parsed.Body,
		parsed.RawContent,
		parsed.WordCount,
		metaJSON,
		checksum,
		created.UTC().Format("2006-01-02 15:04:05.999999999+00:00"),
		modified.UTC().Format("2006-01-02 15:04:05.999999999+00:00"),
	)
	if err != nil {
		return fmt.Errorf("database query: \n\t\t\t\t\tINSERT INTO notes (path, sortable_path, filename, title, lead, body, raw_content, word_count, metadata, checksum, created, modified)\n\t\t\t\t\tVALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)\n\t\t\t\t: %v", err)
	}

	noteID := nb.DB.LastInsertRowID()

	// Update FTS5
	nb.DB.Exec(`
		INSERT INTO notes_fts(rowid, path, title, lead, body, raw_content)
		VALUES (?, ?, ?, ?, ?, ?)
	`, noteID, relPath, parsed.Title, parsed.Lead, parsed.Body, parsed.RawContent)

	// Add tags
	if err := nb.updateNoteTags(noteID, parsed.Tags); err != nil {
		return fmt.Errorf("failed to associate note %d to collection: %v", noteID, err)
	}

	// Add links (we'll resolve targets later or now)
	if err := nb.updateNoteLinks(noteID, relPath, parsed.Links); err != nil {
		return err
	}

	return nil
}

// updateNote updates an existing note in the database
func (nb *Notebook) updateNote(id int64, relPath string, parsed *ParsedNote, created, modified time.Time, checksum string) error {
	metaJSON := NoteMetadataJSON(parsed.Metadata)
	filename := filepath.Base(relPath)
	sortablePath := SortablePath(relPath)

	err := nb.DB.Exec(`
		UPDATE notes SET
			sortable_path = ?,
			filename = ?,
			title = ?,
			lead = ?,
			body = ?,
			raw_content = ?,
			word_count = ?,
			metadata = ?,
			checksum = ?,
			modified = ?
		WHERE id = ?
	`,
		sortablePath,
		filename,
		parsed.Title,
		parsed.Lead,
		parsed.Body,
		parsed.RawContent,
		parsed.WordCount,
		metaJSON,
		checksum,
		modified.UTC().Format("2006-01-02 15:04:05.999999999+00:00"),
		id,
	)
	if err != nil {
		return err
	}

	// Update FTS5
	nb.DB.Exec(`
		INSERT INTO notes_fts(notes_fts, rowid, path, title, lead, body, raw_content)
		VALUES('delete', ?, ?, ?, ?, ?, ?)
	`, id, relPath, "", "", "", "")
	nb.DB.Exec(`
