// updateNoteTags updates the tags for a note
func (nb *Notebook) updateNoteTags(noteID int64, tags []string) error {
	for i, tag := range tags {
		// Get or create collection
		collID, err := nb.getOrCreateCollection("tag", tag)
		if err != nil {
			return fmt.Errorf("failed to associate note %d to collection %d: %v", noteID, i+1, err)
		}

		// Link note to collection
		if err := nb.associateNoteCollection(noteID, collID); err != nil {
			return fmt.Errorf("failed to associate note %d to collection %d: %v", noteID, collID, err)
		}
	}
	return nil
