	row, err := nb.DB.QueryRow("SELECT id FROM collections WHERE kind = ? AND name = ?", kind, name)
	if err != nil {
		return 0, err
	}
	if row != nil {
		return row["id"].(int64), nil
	}

	err = nb.DB.Exec("INSERT INTO collections (kind, name) VALUES (?, ?)", kind, name)
	if err != nil {
