	}
	if row != nil {
		return nil // already exists
	}

	return nb.DB.Exec(
		"INSERT INTO notes_collections (note_id, collection_id) VALUES (?, ?)",
		noteID, collID,
	)
}

// updateNoteLinks updates the links for a note
func (nb *Notebook) updateNoteLinks(noteID int64, sourcePath string, links []ParsedLink) error {
	// Get all note paths for link resolution
	rows, err := nb.DB.QueryRows("SELECT id, path FROM notes")
	if err != nil {
		return err
	}
	pathToID := make(map[string]int64)
	idToPath := make(map[int64]string)
	for _, row := range rows {
		id := row["id"].(int64)
		path := row["path"].(string)
		pathToID[path] = id
		idToPath[id] = path
	}

	for _, link := range links {
		var targetID interface{} = nil

		if !link.External {
			// Resolve the target
			targetPath := resolveLink(link.Href, link.Type, sourcePath, pathToID)
			if targetPath != "" {
				if tid, ok := pathToID[targetPath]; ok {
					targetID = tid
				}
			}
		}

		external := 0
		if link.External {
			external = 1
		}

		rels := strings.Join(link.Rels, ",")

		err := nb.DB.Exec(`
			INSERT INTO links (source_id, target_id, title, href, type, is_external, external, rels, snippet, snippet_start, snippet_end)
			VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
		`,
			noteID,
			targetID,
			link.Title,
			link.Href,
			link.Type,
			external,
			external,
			rels,
			link.Snippet,
			link.SnippetStart,
			link.SnippetEnd,
		)
		if err != nil {
			return err
		}
	}
	return nil
}

// resolveLink resolves a link href to a note path
func resolveLink(href, linkType, sourcePath string, pathToID map[string]int64) string {
	// For wiki-links, try to find by stem
	for path := range pathToID {
		stem := strings.TrimSuffix(path, ".md")
		stem = strings.TrimSuffix(stem, ".markdown")

		// Basename match
		lastSlash := strings.LastIndex(stem, "/")
		basename := stem
		if lastSlash >= 0 {
			basename = stem[lastSlash+1:]
		}

		if href == basename || href == stem || href == path {
			return path
		}
	}

	// For markdown links, try the href directly (with or without extension)
	if linkType == "markdown" {
		// Try relative to source
		sourceDir := filepath.Dir(sourcePath)
		relPath := filepath.Join(sourceDir, href)
		relPath = filepath.ToSlash(relPath)
		if _, ok := pathToID[relPath]; ok {
			return relPath
		}
		if _, ok := pathToID[href]; ok {
			return href
		}
	}

	return ""
}

// isExcluded checks if a path matches any exclude patterns
func (nb *Notebook) isExcluded(relPath string) bool {
	for _, pattern := range nb.Config.Note.Exclude {
		if matchGlob(pattern, relPath) {
			return true
		}
	}
	return false
}

// matchGlob matches a path against a glob pattern
func matchGlob(pattern, path string) bool {
	matched, err := filepath.Match(pattern, path)
	if err != nil {
		return false
	}
	return matched
}

// setMetadata sets a metadata value in the database
func (nb *Notebook) setMetadata(key, value string) error {
	// Check if key exists
	row, err := nb.DB.QueryRow("SELECT key, value FROM metadata WHERE key = ?", key)
	if err != nil {
		return fmt.Errorf("database query: \n\t\t\t\tSELECT key, value FROM metadata WHERE key = ?\n\t\t\t: %v", err)
	}
	if row != nil {
		return nb.DB.Exec("UPDATE metadata SET value = ? WHERE key = ?", value, key)
	}
	return nb.DB.Exec("INSERT INTO metadata (key, value) VALUES (?, ?)", key, value)
}

// IndexSingleNote indexes a single note file
func (nb *Notebook) IndexSingleNote(absPath string) error {
	relPath := nb.RelPath(absPath)

	content, err := os.ReadFile(absPath)
	if err != nil {
		return err
	}
	contentStr := string(content)

	fileInfo, err := os.Stat(absPath)
	if err != nil {
		return err
	}
	modTime := fileInfo.ModTime()
	checksum := NoteChecksum(contentStr)

	parser := &MarkdownParser{Config: nb.Config.Markdown}
	parsedNote := parser.ParseNote(contentStr)

	// Set reindexing flag (ignore error for forward compat)
	nb.setMetadata("zk.reindexing_required", "false")

	// Check if note exists
	row, err := nb.DB.QueryRow("SELECT id, created FROM notes WHERE path = ?", relPath)
	if err != nil {
		return err
	}

	if row != nil {
		id := row["id"].(int64)
		created := time.Now()
		if v := row["created"]; v != nil {
			created, _ = parseTimeString(v.(string))
		}
		return nb.updateNote(id, relPath, parsedNote, created, modTime, checksum)
	}
	return nb.addNote(relPath, parsedNote, modTime, modTime, checksum)
}
