// ParseNoteSort parses a sort term like "title", "title-", "created+"
func ParseNoteSort(term string) (NoteSort, error) {
	asc := true
	if strings.HasSuffix(term, "-") {
		asc = false
		term = term[:len(term)-1]
	} else if strings.HasSuffix(term, "+") {
		asc = true
		term = term[:len(term)-1]
	}

	switch term {
	case "path", "title", "word-count", "created", "modified", "random":
		return NoteSort{Field: term, Ascending: asc}, nil
	default:
		return NoteSort{}, fmt.Errorf("unknown sort field: %q", term)
	}
}

// NoteResult contains the result of a note query
type NoteResult struct {
