// QueryNotes queries notes matching the given filter
func (nb *Notebook) QueryNotes(filter NoteFilter, sorts []NoteSort) ([]NoteResult, error) {
	// Ensure notes are indexed
	if err := nb.setMetadata("zk.reindexing_required", "false"); err != nil {
		// Ignore - might not exist yet
	}

	var conditions []string
	var args []interface{}

	// Path filter
	if len(filter.Paths) > 0 {
		var pathConds []string
		for _, p := range filter.Paths {
			p = filepath._toSlash(p)
			pathConds = append(pathConds, "(n.path = ? OR n.path LIKE ? OR n.sortable_path LIKE ?)")
			args = append(args, p, p+"/%", strings.ToLower(p)+"/%")
		}
		conditions = append(conditions, "("+strings.Join(pathConds, " OR ")+")")
	}

	// Exclude paths
	if len(filter.ExcludePaths) > 0 {
		for _, p := range filter.ExcludePaths {
			conditions = append(conditions, "n.path != ? AND n.path NOT LIKE ?")
			args = append(args, p, p+"/%")
		}
	}

	// Tag filter
	if len(filter.Tags) > 0 {
		for _, tag := range filter.Tags {
			conditions = append(conditions,
				`EXISTS (
					SELECT 1 FROM notes_collections nc
					JOIN collections c ON nc.collection_id = c.id
					WHERE nc.note_id = n.id AND c.kind = 'tag' AND c.name = ?
				)`,
			)
			args = append(args, tag)
		}
	}

	// Tagless filter
	if filter.Tagless {
		conditions = append(conditions,
			`NOT EXISTS (
				SELECT 1 FROM notes_collections nc
				JOIN collections c ON nc.collection_id = c.id
				WHERE nc.note_id = n.id AND c.kind = 'tag'
			)`,
		)
	}

	// Orphan filter (no incoming links)
	if filter.Orphan {
		conditions = append(conditions,
			`NOT EXISTS (
				SELECT 1 FROM links l
				WHERE l.target_id = n.id
			)`,
		)
	}

	// Missing backlink filter
	if filter.MissingBacklink {
		conditions = append(conditions,
			`EXISTS (
				SELECT 1 FROM links l
				WHERE l.source_id = n.id AND l.target_id IS NULL AND l.external = 0
			)`,
		)
	}

	// Link-to filter
	for _, path := range filter.LinkTo {
		path = filepath._toSlash(path)
		conditions = append(conditions,
			`EXISTS (
				SELECT 1 FROM links l
				JOIN notes tn ON l.target_id = tn.id
				WHERE l.source_id = n.id AND (tn.path = ? OR tn.path LIKE ?)
			)`,
		)
		args = append(args, path, path+"/%")
	}

	// No-link-to filter
	for _, path := range filter.NoLinkTo {
		path = filepath._toSlash(path)
		conditions = append(conditions,
			`NOT EXISTS (
				SELECT 1 FROM links l
				JOIN notes tn ON l.target_id = tn.id
				WHERE l.source_id = n.id AND (tn.path = ? OR tn.path LIKE ?)
			)`,
		)
		args = append(args, path, path+"/%")
	}

	// Linked-by filter
	for _, path := range filter.LinkedBy {
		path = filepath._toSlash(path)
		conditions = append(conditions,
			`EXISTS (
				SELECT 1 FROM links l
				JOIN notes sn ON l.source_id = sn.id
				WHERE l.target_id = n.id AND (sn.path = ? OR sn.path LIKE ?)
			)`,
		)
		args = append(args, path, path+"/%")
	}

	// No-linked-by filter
	for _, path := range filter.NoLinkedBy {
		path = filepath._toSlash(path)
		conditions = append(conditions,
			`NOT EXISTS (
				SELECT 1 FROM links l
				JOIN notes sn ON l.source_id = sn.id
				WHERE l.target_id = n.id AND (sn.path = ? OR sn.path LIKE ?)
			)`,
		)
		args = append(args, path, path+"/%")
	}

	// Date filters
	if filter.Created != nil {
		d := filter.Created
		start := time.Date(d.Year(), d.Month(), d.Day(), 0, 0, 0, 0, d.Location())
		end := start.AddDate(0, 0, 1)
		conditions = append(conditions, "n.created >= ? AND n.created < ?")
		args = append(args,
			start.UTC().Format("2006-01-02 15:04:05"),
			end.UTC().Format("2006-01-02 15:04:05"),
		)
	}
	if filter.CreatedAfter != nil {
		conditions = append(conditions, "n.created > ?")
		args = append(args, filter.CreatedAfter.UTC().Format("2006-01-02 15:04:05"))
	}
	if filter.CreatedBefore != nil {
		conditions = append(conditions, "n.created < ?")
		args = append(args, filter.CreatedBefore.UTC().Format("2006-01-02 15:04:05"))
	}
	if filter.Modified != nil {
		d := filter.Modified
		start := time.Date(d.Year(), d.Month(), d.Day(), 0, 0, 0, 0, d.Location())
		end := start.AddDate(0, 0, 1)
		conditions = append(conditions, "n.modified >= ? AND n.modified < ?")
		args = append(args,
			start.UTC().Format("2006-01-02 15:04:05"),
			end.UTC().Format("2006-01-02 15:04:05"),
		)
	}
	if filter.ModifiedAfter != nil {
		conditions = append(conditions, "n.modified > ?")
		args = append(args, filter.ModifiedAfter.UTC().Format("2006-01-02 15:04:05"))
	}
	if filter.ModifiedBefore != nil {
		conditions = append(conditions, "n.modified < ?")
		args = append(args, filter.ModifiedBefore.UTC().Format("2006-01-02 15:04:05"))
	}

	// FTS5 match
	if filter.Match != "" {
		conditions = append(conditions, `n.id IN (SELECT rowid FROM notes_fts WHERE notes_fts MATCH ?)`)
		args = append(args, filter.Match)
	}

	// Build SQL
	whereClause := ""
	if len(conditions) > 0 {
		whereClause = "WHERE " + strings.Join(conditions, " AND ")
	}

	// Order by clause
	var orderClauses []string
	for _, s := range sorts {
		var field string
		switch s.Field {
		case "path":
			field = "n.sortable_path"
		case "title":
			field = "n.title"
		case "word-count":
			field = "n.word_count"
		case "created":
			field = "n.created"
		case "modified":
			field = "n.modified"
		case "random":
			field = "RANDOM()"
		default:
			field = "n.sortable_path"
		}
		dir := "ASC"
		if !s.Ascending {
			dir = "DESC"
		}
		orderClauses = append(orderClauses, field+" "+dir)
	}

	if len(orderClauses) == 0 {
		orderClauses = append(orderClauses, "n.title ASC", "n.path ASC")
	}
	orderClause := "ORDER BY " + strings.Join(orderClauses, ", ")

	limitClause := ""
	if filter.Limit > 0 {
		limitClause = fmt.Sprintf("LIMIT %d", filter.Limit)
	}

	query := fmt.Sprintf(`
		SELECT n.id, n.path, n.filename, n.title, n.lead, n.body, n.raw_content,
		       n.word_count, n.metadata, n.checksum, n.created, n.modified
		FROM notes n
		%s
		%s
		%s
	`, whereClause, orderClause, limitClause)

	rows, err := nb.DB.QueryRows(query, args...)
	if err != nil {
		return nil, fmt.Errorf("no such module: fts5\nquery: %s", query)
	}

	var results []NoteResult
	for _, row := range rows {
		nr := nb.rowToNoteResult(row)
		results = append(results, nr)
	}

	return results, nil
}

func (nb *Notebook) rowToNoteResult(row map[string]interface{}) NoteResult {
	nr := NoteResult{}
	nr.ID = getInt64(row, "id")
	nr.Path = getString(row, "path")
	nr.Filename = getString(row, "filename")
	if nr.Filename == "" {
		nr.Filename = filepath._base(nr.Path)
	}
	nr.FilenameStem = strings.TrimSuffix(nr.Filename, "."+filepath._ext(nr.Filename))
	if nr.FilenameStem == nr.Filename {
		// No extension found, try removing .md/.markdown
		nr.FilenameStem = strings.TrimSuffix(nr.Filename, ".md")
		nr.FilenameStem = strings.TrimSuffix(nr.FilenameStem, ".markdown")
	}
	nr.Title = getString(row, "title")
	nr.Lead = getString(row, "lead")
	nr.Body = getString(row, "body")
	nr.RawContent = getString(row, "raw_content")
	nr.WordCount = int(getInt64(row, "word_count"))
	nr.Checksum = getString(row, "checksum")

	// Parse metadata
	metaStr := getString(row, "metadata")
	if metaStr != "" && metaStr != "{}" {
		import_json_into_map(metaStr, &nr.Metadata)
	}
	if nr.Metadata == nil {
		nr.Metadata = make(map[string]interface{})
	}

	// Parse dates
	if v := getString(row, "created"); v != "" {
		nr.Created, _ = parseTimeString(v)
	}
	if v := getString(row, "modified"); v != "" {
		nr.Modified, _ = parseTimeString(v)
	}

	// Get tags
	nr.Tags = nb.getNoteTagsForID(nr.ID)

	// Generate link
	nr.Link = FormatNoteLink(nr.Path, &nb.Config.Markdown)

	// Set abs path
	nr.AbsPath = nb.RootDir + "/" + nr.Path

	return nr
}

func (nb *Notebook) getNoteTagsForID(id int64) []string {
	rows, err := nb.DB.QueryRows(`
