		JOIN notes_collections nc ON nc.collection_id = c.id
		WHERE nc.note_id = ? AND c.kind = 'tag'
		ORDER BY c.name
	`, id)
	if err != nil {
		return nil
	}
	var tags []string
	for _, row := range rows {
		tags = append(tags, getString(row, "name"))
	}
	return tags
}

