// QueryTags queries tags from the database
func (nb *Notebook) QueryTags(filter TagFilter, sorts []TagSort) ([]TagResult, error) {
	var orderClauses []string
	for _, s := range sorts {
		var field string
		switch s.Field {
		case "name":
			field = "c.name"
		case "note-count":
			field = "COUNT(nc.note_id)"
		default:
			field = "c.name"
		}
		dir := "ASC"
		if !s.Ascending {
			dir = "DESC"
		}
		orderClauses = append(orderClauses, field+" "+dir)
	}
	if len(orderClauses) == 0 {
		orderClauses = append(orderClauses, "c.name ASC")
	}

	query := fmt.Sprintf(`
		SELECT c.id, c.kind, c.name, COUNT(nc.note_id) as note_count
		FROM collections c
		LEFT JOIN notes_collections nc ON nc.collection_id = c.id
		WHERE c.kind = 'tag'
		GROUP BY c.id
		ORDER BY %s
	`, strings.Join(orderClauses, ", "))

	rows, err := nb.DB.QueryRows(query)
	if err != nil {
