func (nb *Notebook) rowToNoteResult(row map[string]interface{}) NoteResult {
	nr := NoteResult{}
	nr.ID = getInt64(row, "id")
	nr.Path = getString(row, "path")
	nr.Filename = getString(row, "filename")
	if nr.Filename == "" {
		nr.Filename = filepath._base(nr.Path)
	}
	nr.FilenameStem = strings.TrimSuffix(nr.Filename, "."+filepath._ext(nr.Filename))
	if nr.FilenameStem == nr.Filename {
		// No extension found, try removing .md/.markdown
		nr.FilenameStem = strings.TrimSuffix(nr.Filename, ".md")
		nr.FilenameStem = strings.TrimSuffix(nr.FilenameStem, ".markdown")
	}
	nr.Title = getString(row, "title")
	nr.Lead = getString(row, "lead")
	nr.Body = getString(row, "body")
	nr.RawContent = getString(row, "raw_content")
	nr.WordCount = int(getInt64(row, "word_count"))
	nr.Checksum = getString(row, "checksum")

	// Parse metadata
	metaStr := getString(row, "metadata")
	if metaStr != "" && metaStr != "{}" {
		import_json_into_map(metaStr, &nr.Metadata)
	}
	if nr.Metadata == nil {
		nr.Metadata = make(map[string]interface{})
	}

	// Parse dates
	if v := getString(row, "created"); v != "" {
		nr.Created, _ = parseTimeString(v)
	}
	if v := getString(row, "modified"); v != "" {
		nr.Modified, _ = parseTimeString(v)
	}

	// Get tags
	nr.Tags = nb.getNoteTagsForID(nr.ID)

	// Generate link
	nr.Link = FormatNoteLink(nr.Path, &nb.Config.Markdown)

	// Set abs path
	nr.AbsPath = nb.RootDir + "/" + nr.Path

	return nr
}

func (nb *Notebook) getNoteTagsForID(id int64) []string {
	rows, err := nb.DB.QueryRows(`
		SELECT c.name FROM collections c
		JOIN notes_collections nc ON nc.collection_id = c.id
		WHERE nc.note_id = ? AND c.kind = 'tag'
		ORDER BY c.name
	`, id)
	if err != nil {
		return nil
	}
	var tags []string
	for _, row := range rows {
		tags = append(tags, getString(row, "name"))
	}
	return tags
}

func getString(row map[string]interface{}, key string) string {
	if v, ok := row[key]; ok && v != nil {
		if s, ok := v.(string); ok {
			return s
		}
	}
	return ""
}

func getInt64(row map[string]interface{}, key string) int64 {
	if v, ok := row[key]; ok && v != nil {
		if n, ok := v.(int64); ok {
			return n
		}
	}
	return 0
}

func import_json_into_map(s string, m *map[string]interface{}) {
	// Simple JSON object parsing
	*m = make(map[string]interface{})
	// Use encoding/json
	import_json_parse(s, m)
}

// TagResult represents a tag query result
type TagResult struct {
	ID        int64
	Kind      string
	Name      string
	NoteCount int
}

// TagFilter contains filter criteria for tags
type TagFilter struct {
	Names []string
	Match string
	Limit int
}

// TagSort specifies how to sort tags
type TagSort struct {
	Field     string
	Ascending bool
}

// ParseTagSort parses a sort term for tags
func ParseTagSort(term string) (TagSort, error) {
	asc := true
	if strings.HasSuffix(term, "-") {
		asc = false
		term = term[:len(term)-1]
	} else if strings.HasSuffix(term, "+") {
		asc = true
		term = term[:len(term)-1]
	}

	switch term {
	case "name", "note-count":
		return TagSort{Field: term, Ascending: asc}, nil
	default:
		return TagSort{}, fmt.Errorf("unknown sort field for tags: %q", term)
	}
}

// QueryTags queries tags from the database
func (nb *Notebook) QueryTags(filter TagFilter, sorts []TagSort) ([]TagResult, error) {
	var orderClauses []string
	for _, s := range sorts {
		var field string
		switch s.Field {
		case "name":
			field = "c.name"
		case "note-count":
			field = "COUNT(nc.note_id)"
		default:
			field = "c.name"
		}
		dir := "ASC"
		if !s.Ascending {
			dir = "DESC"
		}
		orderClauses = append(orderClauses, field+" "+dir)
	}
	if len(orderClauses) == 0 {
		orderClauses = append(orderClauses, "c.name ASC")
	}

	query := fmt.Sprintf(`
		SELECT c.id, c.kind, c.name, COUNT(nc.note_id) as note_count
		FROM collections c
		LEFT JOIN notes_collections nc ON nc.collection_id = c.id
		WHERE c.kind = 'tag'
		GROUP BY c.id
		ORDER BY %s
	`, strings.Join(orderClauses, ", "))

	rows, err := nb.DB.QueryRows(query)
	if err != nil {
		return nil, err
	}

	var results []TagResult
	for _, row := range rows {
		tr := TagResult{
			ID:        getInt64(row, "id"),
			Kind:      getString(row, "kind"),
			Name:      getString(row, "name"),
			NoteCount: int(getInt64(row, "note_count")),
		}
		results = append(results, tr)
	}
	return results, nil
}

// LinkResult represents a link in the graph
type LinkResult struct {
	SourceID   int64
	SourcePath string
	TargetID   int64
	TargetPath string
	Title      string
	Href       string
	Type       string
	External   bool
	Rels       []string
	Snippet    string
	SnippetStart int
	SnippetEnd   int
}

// QueryLinks queries links for the graph
func (nb *Notebook) QueryLinks(noteIDs []int64) ([]LinkResult, error) {
	if len(noteIDs) == 0 {
		return nil, nil
	}

	placeholders := make([]string, len(noteIDs))
	args := make([]interface{}, len(noteIDs))
	for i, id := range noteIDs {
		placeholders[i] = "?"
		args[i] = id
	}

	query := fmt.Sprintf(`
		SELECT l.source_id, sn.path as source_path,
		       l.target_id, tn.path as target_path,
		       l.title, l.href, l.type, l.external, l.rels,
		       l.snippet, l.snippet_start, l.snippet_end
		FROM links l
		JOIN notes sn ON l.source_id = sn.id
		LEFT JOIN notes tn ON l.target_id = tn.id
		WHERE l.source_id IN (%s)
	`, strings.Join(placeholders, ","))

	rows, err := nb.DB.QueryRows(query, args...)
	if err != nil {
		return nil, err
	}

	var results []LinkResult
	for _, row := range rows {
		lr := LinkResult{
			SourceID:     getInt64(row, "source_id"),
			SourcePath:   getString(row, "source_path"),
			TargetID:     getInt64(row, "target_id"),
			TargetPath:   getString(row, "target_path"),
			Title:        getString(row, "title"),
			Href:         getString(row, "href"),
			Type:         getString(row, "type"),
			External:     getInt64(row, "external") != 0,
			Snippet:      getString(row, "snippet"),
			SnippetStart: int(getInt64(row, "snippet_start")),
			SnippetEnd:   int(getInt64(row, "snippet_end")),
		}
		if relsStr := getString(row, "rels"); relsStr != "" {
			lr.Rels = strings.Split(relsStr, ",")
		}
		results = append(results, lr)
	}
	return results, nil
}
