		JOIN notes sn ON l.source_id = sn.id
		LEFT JOIN notes tn ON l.target_id = tn.id
		WHERE l.source_id IN (%s)
	`, strings.Join(placeholders, ","))

	rows, err := nb.DB.QueryRows(query, args...)
	if err != nil {
		return nil, err
	}

	var results []LinkResult
	for _, row := range rows {
		lr := LinkResult{
			SourceID:     getInt64(row, "source_id"),
			SourcePath:   getString(row, "source_path"),
			TargetID:     getInt64(row, "target_id"),
			TargetPath:   getString(row, "target_path"),
			Title:        getString(row, "title"),
			Href:         getString(row, "href"),
			Type:         getString(row, "type"),
			External:     getInt64(row, "external") != 0,
			Snippet:      getString(row, "snippet"),
			SnippetStart: int(getInt64(row, "snippet_start")),
			SnippetEnd:   int(getInt64(row, "snippet_end")),
		}
		if relsStr := getString(row, "rels"); relsStr != "" {
			lr.Rels = strings.Split(relsStr, ",")
		}
		results = append(results, lr)
	}
	return results, nil
}
