	ext := filepath.Ext(nr.Filename)
	if ext != "" {
		nr.FilenameStem = strings.TrimSuffix(nr.Filename, ext)
	} else {
		nr.FilenameStem = nr.Filename
	}
	nr.Title = getString(row, "title")
	nr.Lead = getString(row, "lead")
	nr.Body = getString(row, "body")
	nr.RawContent = getString(row, "raw_content")
	nr.WordCount = int(getInt64(row, "word_count"))
	nr.Checksum = getString(row, "checksum")

