package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
	"zk/internal"
)

// Global flags
var (
	flagNotebookDir string
	flagWorkingDir  string
	flagNoInput     bool
)

func main() {
	args := os.Args[1:]

	// Parse global flags first
	var remainingArgs []string
	i := 0
	for i < len(args) {
		switch args[i] {
		case "--notebook-dir":
			i++
			if i < len(args) {
				flagNotebookDir = args[i]
			}
		case "--notebook-dir=" + "":
			// handled below
		case "--no-input":
			flagNoInput = true
		case "-W", "--working-dir":
			i++
			if i < len(args) {
				flagWorkingDir = args[i]
			}
		case "-h", "--help":
			printHelp()
			os.Exit(0)
		default:
			if strings.HasPrefix(args[i], "--notebook-dir=") {
				flagNotebookDir = args[i][len("--notebook-dir="):]
			} else if strings.HasPrefix(args[i], "-W=") {
				flagWorkingDir = args[i][3:]
			} else if strings.HasPrefix(args[i], "--working-dir=") {
				flagWorkingDir = args[i][len("--working-dir="):]
			} else {
				remainingArgs = append(remainingArgs, args[i])
			}
		}
		i++
	}

	if len(remainingArgs) == 0 {
		printHelp()
		os.Exit(0)
	}

	cmd := remainingArgs[0]
	cmdArgs := remainingArgs[1:]

	// Determine working directory
	workingDir, err := os.Getwd()
	if err != nil {
		workingDir = "."
	}
	if flagWorkingDir != "" {
		if filepath.IsAbs(flagWorkingDir) {
			workingDir = flagWorkingDir
		} else {
			workingDir = filepath.Join(workingDir, flagWorkingDir)
		}
	}

	switch cmd {
	case "init":
		if err := cmdInit(cmdArgs, workingDir); err != nil {
			exitError(err)
		}
	case "index":
		if err := cmdIndex(cmdArgs, workingDir); err != nil {
			exitError(err)
		}
	case "new":
		if err := cmdNew(cmdArgs, workingDir); err != nil {
			exitError(err)
		}
	case "list":
		if err := cmdList(cmdArgs, workingDir); err != nil {
			exitError(err)
		}
	case "graph":
		if err := cmdGraph(cmdArgs, workingDir); err != nil {
			exitError(err)
		}
	case "edit":
		if err := cmdEdit(cmdArgs, workingDir); err != nil {
			exitError(err)
		}
	case "tag":
		if len(cmdArgs) == 0 {
			printTagHelp()
			os.Exit(0)
		}
		switch cmdArgs[0] {
		case "list":
			if err := cmdTagList(cmdArgs[1:], workingDir); err != nil {
				exitError(err)
			}
		default:
			printTagHelp()
			os.Exit(0)
		}
	default:
		// Check for alias
		nb, err := openNotebook(workingDir)
		if err == nil {
			defer nb.Close()
			if aliasCmd, ok := nb.Config.Aliases[cmd]; ok {
				if err := runAlias(aliasCmd, cmdArgs, nb); err != nil {
					exitError(err)
				}
				return
			}
			// Check filters
			if filterStr, ok := nb.Config.Filters[cmd]; ok {
				filterArgs := parseShellArgs(filterStr)
				allArgs := append(filterArgs, cmdArgs...)
				if err := cmdList(allArgs, workingDir); err != nil {
					exitError(err)
				}
				return
			}
		}
		fmt.Fprintf(os.Stderr, "zk: error: unknown command %q\n", cmd)
		os.Exit(1)
	}
}

func exitError(err error) {
	fmt.Fprintf(os.Stderr, "zk: error: %v\n", err)
	os.Exit(1)
}

func openNotebook(workingDir string) (*internal.Notebook, error) {
	var notebookDir string
	var err error

	if flagNotebookDir != "" {
		notebookDir = flagNotebookDir
		if !filepath.IsAbs(notebookDir) {
			notebookDir = filepath.Join(workingDir, notebookDir)
		}
	} else {
		notebookDir, err = internal.FindNotebook(workingDir)
		if err != nil {
			return nil, fmt.Errorf("no notebook found in %s or a parent directory", workingDir)
		}
	}

	nb, err := internal.OpenNotebook(notebookDir)
	if err != nil {
		return nil, fmt.Errorf("failed to open notebook: %v", err)
	}
	return nb, nil
}

