// cmdInit implements the init command
func cmdInit(args []string, workingDir string) error {
	dir := workingDir
	if len(args) > 0 && !strings.HasPrefix(args[0], "-") {
		d := args[0]
		if !filepath.IsAbs(d) {
			d = filepath.Join(workingDir, d)
		}
		dir = d
	}

	// Check for help
	for _, a := range args {
		if a == "-h" || a == "--help" {
			printInitHelp()
			return nil
		}
	}

	// Ask about wiki links if not --no-input
	wikiLinks := true // default
	if !flagNoInput {
		wikiLinks = promptYesNo("Do you prefer [[WikiLinks]] over regular Markdown links?", false)
	}

	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}

	if err := internal.InitNotebook(dir, wikiLinks); err != nil {
		return fmt.Errorf("failed to open notebook: %v", err)
	}

	return nil
}

