// promptYesNo prompts the user for a yes/no answer
func promptYesNo(question string, defaultYes bool) bool {
	opts := "(y/N)"
	if defaultYes {
		opts = "(Y/n)"
	}

	// Output with ANSI colors to match original
	fmt.Fprintf(os.Stderr, "\033[0G\033[2K\033[0;1;92m? \033[0m\033[0;1;99m%s \033[0m\033[0;37m%s \033[0m", question, opts)

	reader := bufio.NewReader(os.Stdin)
	response, err := reader.ReadString('\n')
	if err != nil {
		if err == io.EOF {
			fmt.Fprintln(os.Stderr, "")
			exitError(fmt.Errorf("EOF"))
		}
		return defaultYes
	}

	response = strings.TrimSpace(strings.ToLower(response))
	if response == "y" || response == "yes" {
		return true
	}
	if response == "n" || response == "no" {
		return false
	}
	return defaultYes
}

// cmdIndex implements the index command
func cmdIndex(args []string, workingDir string) error {
	var force, verbose, quiet bool

	remaining := parseFlags(args, func(flag, val string) bool {
		switch flag {
		case "-f", "--force":
			force = true
		case "-v", "--verbose":
			verbose = true
		case "-q", "--quiet":
			quiet = true
		case "-h", "--help":
			printIndexHelp()
			os.Exit(0)
		default:
			return false
		}
		return true
	})
	_ = remaining

	nb, err := openNotebook(workingDir)
	if err != nil {
		return err
	}
	defer nb.Close()

	start := time.Now()
	stats, err := nb.IndexNotebook(internal.IndexOptions{
		Force:   force,
		Verbose: verbose,
		Quiet:   quiet,
	})
	if err != nil {
		return fmt.Errorf("indexing: %v", err)
	}
	elapsed := time.Since(start)

	if !quiet {
		totalStr := "s"
		if elapsed.Milliseconds() < 1000 {
			totalStr = "s"
		}
		fmt.Printf("Indexed %d note%s in %s\n", stats.Added+stats.Modified+stats.Removed+stats.Unchanged, 
			pluralS(stats.Added+stats.Modified+stats.Removed+stats.Unchanged),
			formatDuration(elapsed))
		fmt.Printf("  + %d added\n", stats.Added)
		fmt.Printf("  ~ %d modified\n", stats.Modified)
		fmt.Printf("  - %d removed\n", stats.Removed)
		_ = totalStr
	}

	return nil
}

func formatDuration(d time.Duration) string {
	if d < time.Second {
		return "0s"
	}
	return fmt.Sprintf("%ds", int(d.Seconds()))
}

func pluralS(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

func printIndexHelp() {
	fmt.Print(`Usage: zk index

Index the notes to be searchable.

You usually do not need to run ` + "`" + `zk index` + "`" + ` manually, as notes are indexed
automatically when needed.

Flags:
