// cmdNew implements the new command
func cmdNew(args []string, workingDir string) error {
	var (
		title     string
		date      string
		group     string
		extra     []string
		tmplPath  string
		printPath bool
		dryRun    bool
		noteID    string
		interactive bool
	)

	var pathArgs []string
	remaining := parseFlags(args, func(flag, val string) bool {
		switch flag {
		case "-t", "--title":
			title = val
		case "-g", "--group":
			group = val
		case "--date":
			date = val
		case "--extra":
			extra = append(extra, val)
		case "--template":
			tmplPath = val
		case "-p", "--print-path":
			printPath = true
		case "-n", "--dry-run":
			dryRun = true
		case "--id":
			noteID = val
		case "-i", "--interactive":
			interactive = true
		case "-h", "--help":
			printNewHelp()
			os.Exit(0)
		default:
			return false
		}
		return true
	})
	for _, a := range remaining {
		if !strings.HasPrefix(a, "-") {
			pathArgs = append(pathArgs, a)
		}
	}

	nb, err := openNotebook(workingDir)
	if err != nil {
		return err
	}
	defer nb.Close()

	// Determine target directory
	targetDir := workingDir
	if len(pathArgs) > 0 {
		d := pathArgs[0]
		if !filepath.IsAbs(d) {
			// Try relative to working dir
			absD := filepath.Join(workingDir, d)
			if fi, err := os.Stat(absD); err == nil && fi.IsDir() {
				targetDir = absD
			} else {
				// Maybe it's relative to notebook root
				absD2 := filepath.Join(nb.RootDir, d)
				if fi2, err := os.Stat(absD2); err == nil && fi2.IsDir() {
					targetDir = absD2
				} else {
					targetDir = absD
				}
			}
		} else {
			targetDir = d
		}
	}

	// Make sure targetDir is inside the notebook
	relDir, err := filepath.Rel(nb.RootDir, targetDir)
	if err != nil || strings.HasPrefix(relDir, "..") {
		return fmt.Errorf("new note: %s: path is outside the notebook at %s", targetDir, nb.RootDir)
	}

	// Get note config for this directory
	noteCfg := nb.Config.NoteConfigForPath(relDir)
	extraVars := nb.Config.ExtraForPath(relDir)

	// Override with group if specified
	if group != "" {
		if grp, ok := nb.Config.Groups[group]; ok {
			noteCfg = grp.Note
			for k, v := range grp.Extra {
				extraVars[k] = v
			}
		}
	}

	// Parse extra variables from command line
	for _, e := range extra {
		parts := strings.SplitN(e, "=", 2)
		if len(parts) == 2 {
			extraVars[parts[0]] = parts[1]
		}
	}

	// Parse date
	var now time.Time
	if date != "" {
		t, err := time.Parse("2006-01-02", date)
		if err != nil {
			t, err = internal.ParseRelativeDate(date)
			if err != nil {
				return fmt.Errorf("invalid date: %s", date)
			}
		}
		now = t
	} else {
		now = time.Now()
	}

	// Set default title
	if title == "" {
		title = noteCfg.DefaultTitle
	}

	// Generate ID
	if noteID == "" {
		noteID = nb.GenerateUniqueID(noteCfg)
	}

	// Determine filename using template
	filenameTmpl := noteCfg.Filename
	if filenameTmpl == "" {
		filenameTmpl = "{{id}}"
	}

	filenameCtx := internal.TemplateContext{
		"id":    noteID,
		"title": title,
		"dir":   relDir,
		"now":   now,
	}
	for k, v := range extraVars {
		filenameCtx["extra."+k] = v
		if filenameCtx["extra"] == nil {
			filenameCtx["extra"] = extraVars
		}
	}

	filename, err := internal.RenderTemplate(filenameTmpl, filenameCtx)
	if err != nil {
		return fmt.Errorf("render filename template: %v", err)
	}

	// Add extension
	ext := noteCfg.Extension
	if ext == "" {
		ext = "md"
	}
	if !strings.HasSuffix(filename, "."+ext) {
		filename = filename + "." + ext
	}

	// Full path
	notePath := filepath.Join(targetDir, filename)
	noteRelPath := nb.RelPath(notePath)

	// Read content from stdin if --interactive
	var stdinContent string
	if interactive {
		data, err := io.ReadAll(os.Stdin)
		if err == nil {
			stdinContent = strings.TrimRight(string(data), "\n")
		}
	}

	// Load template
	var tmplContent string
	if tmplPath != "" {
		tmplContent, err = nb.LoadTemplate(tmplPath)
	} else if noteCfg.Template != "" {
		tmplContent, err = nb.LoadTemplate(noteCfg.Template)
	} else {
		tmplContent = "# {{title}}\n\n{{content}}\n"
		err = nil
	}
	if err != nil {
		tmplContent = "# {{title}}\n\n{{content}}\n"
	}

	// Render template
	tmplCtx := internal.TemplateContext{
		"id":       noteID,
		"title":    title,
		"content":  stdinContent,
		"dir":      relDir,
		"now":      now,
		"filename": filename,
		"extra":    extraVars,
	}

	noteContent, err := internal.RenderTemplate(tmplContent, tmplCtx)
	if err != nil {
		return fmt.Errorf("render template: %v", err)
	}

	if dryRun {
		// Print path to stderr and content to stdout
		fmt.Fprintln(os.Stderr, notePath)
		fmt.Print(noteContent)
		return nil
	}

	// Create the note file
	if err := os.MkdirAll(filepath.Dir(notePath), 0755); err != nil {
		return err
	}

	if _, err := os.Stat(notePath); err == nil {
		// File already exists - generate new ID
		noteID = nb.GenerateUniqueID(noteCfg)
		filename, _ = internal.RenderTemplate(filenameTmpl, internal.TemplateContext{
			"id":    noteID,
			"title": title,
			"dir":   relDir,
			"now":   now,
			"extra": extraVars,
		})
		if !strings.HasSuffix(filename, "."+ext) {
			filename = filename + "." + ext
		}
		notePath = filepath.Join(targetDir, filename)
		noteRelPath = nb.RelPath(notePath)
		_ = noteRelPath
	}

	if err := os.WriteFile(notePath, []byte(noteContent), 0644); err != nil {
		return err
	}

	// Index the new note
	if err := nb.IndexSingleNote(notePath); err != nil {
		fmt.Fprintf(os.Stderr, "zk: warning: %s: failed to index the note: %v\n", noteRelPath, err)
	}

	if printPath {
		fmt.Println(notePath)
		return nil
	}

	// Open in editor
	editor := nb.Config.Tool.Editor
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		editor = os.Getenv("VISUAL")
	}
	if editor != "" && !flagNoInput {
		cmd := exec.Command("sh", "-c", editor+" "+notePath)
		cmd.Stdin = os.Stdin
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		cmd.Run()
	} else {
		fmt.Println(notePath)
	}

	return nil
}

func printNewHelp() {
	fmt.Print(`Usage: zk new [<directory>]

Create a new note in the given notebook directory.

Arguments:
  [<directory>]    Directory in which to create the note.

Flags:
  -h, --help                   Show context-sensitive help.
      --notebook-dir=PATH      Turn off notebook auto-discovery and set manually
                               the notebook where commands are run.
  -W, --working-dir=PATH       Run as if zk was started in <PATH> instead of the
