// cmdGraph implements the graph command
func cmdGraph(args []string, workingDir string) error {
	var (
		format    string
		quiet     bool
		pathArgs  []string
		sortTerms []string
		// Add filtering options similar to list
		tags        []string
		linkTo      []string
		noLinkTo    []string
		linkedBy    []string
		noLinkedBy  []string
		orphan      bool
		tagless     bool
	)

	remaining := parseFlags(args, func(flag, val string) bool {
		switch flag {
		case "-f", "--format":
			format = val
		case "-q", "--quiet":
			quiet = true
		case "-s", "--sort":
			sortTerms = append(sortTerms, splitComma(val)...)
		case "-t", "--tag":
			tags = append(tags, splitComma(val)...)
		case "-l", "--link-to":
			linkTo = append(linkTo, splitComma(val)...)
		case "--no-link-to":
			noLinkTo = append(noLinkTo, splitComma(val)...)
		case "-L", "--linked-by":
			linkedBy = append(linkedBy, splitComma(val)...)
		case "--no-linked-by":
			noLinkedBy = append(noLinkedBy, splitComma(val)...)
		case "--orphan":
			orphan = true
		case "--tagless":
			tagless = true
		case "-h", "--help":
			printGraphHelp()
			os.Exit(0)
		default:
			return false
		}
		return true
	})
	for _, a := range remaining {
		if !strings.HasPrefix(a, "-") {
			pathArgs = append(pathArgs, a)
		}
	}

	if format == "" {
		return fmt.Errorf("--format is required")
	}

	nb, err := openNotebook(workingDir)
	if err != nil {
		return err
	}
	defer nb.Close()

	// Build filter
	filter := internal.NoteFilter{
		Tags:       tags,
		Orphan:     orphan,
		Tagless:    tagless,
		LinkTo:     linkTo,
		NoLinkTo:   noLinkTo,
		LinkedBy:   linkedBy,
		NoLinkedBy: noLinkedBy,
	}
	for _, p := range pathArgs {
		resolved := resolveNotePath(p, workingDir, nb.RootDir)
		filter.Paths = append(filter.Paths, resolved)
	}

	var sorts []internal.NoteSort
	for _, term := range sortTerms {
		s, err := internal.ParseNoteSort(term)
		if err == nil {
			sorts = append(sorts, s)
		}
	}

	// Run index
	nb.IndexNotebook(internal.IndexOptions{Quiet: true})

	notes, err := nb.QueryNotes(filter, sorts)
	if err != nil {
		return err
	}

	if format == "json" {
		// Build note IDs for link query
		var noteIDs []int64
		for _, n := range notes {
			noteIDs = append(noteIDs, n.ID)
		}

		links, err := nb.QueryLinks(noteIDs)
		if err != nil {
			links = nil
		}

		// Build JSON
		var noteJSONs []json.RawMessage
		for _, n := range notes {
			b, _ := json.Marshal(internal.NoteToJSON(n))
			noteJSONs = append(noteJSONs, b)
		}

		var linkJSONs []json.RawMessage
		for _, l := range links {
			rels := l.Rels
			if rels == nil {
				rels = []string{}
			}
			lj := map[string]interface{}{
				"title":        l.Title,
				"href":         l.Href,
				"type":         l.Type,
				"isExternal":   l.External,
				"rels":         rels,
				"snippet":      l.Snippet,
				"snippetStart": l.SnippetStart,
				"snippetEnd":   l.SnippetEnd,
				"sourceId":     l.SourceID,
				"sourcePath":   l.SourcePath,
				"targetId":     l.TargetID,
				"targetPath":   l.TargetPath,
			}
			b, _ := json.Marshal(lj)
			linkJSONs = append(linkJSONs, b)
		}

		fmt.Print("{\n  \"notes\": [\n")
		for i, n := range noteJSONs {
			if i < len(noteJSONs)-1 {
				fmt.Printf("    %s,\n", n)
			} else {
				fmt.Printf("    %s\n", n)
			}
		}
		fmt.Print("  ],\n  \"links\": [\n")
		for i, l := range linkJSONs {
			if i < len(linkJSONs)-1 {
				fmt.Printf("    %s,\n", l)
			} else {
				fmt.Printf("    %s\n", l)
			}
		}
		fmt.Print("  ]\n}\n")
	}

	if !quiet {
		fmt.Fprintf(os.Stderr, "\nFound %d note%s\n", len(notes), pluralS(len(notes)))
	}

	return nil
}

