// cmdTagList implements the tag list command
func cmdTagList(args []string, workingDir string) error {
	var (
		format    string
		header    string
		footer    = "\n"
		delimiter = "\n"
		delimiter0 bool
		noPager   bool
		quiet     bool
		sortTerms []string
	)

	remaining := parseFlags(args, func(flag, val string) bool {
		switch flag {
		case "-f", "--format":
			format = val
		case "--header":
			header = val
		case "--footer":
			footer = unescapeString(val)
		case "-d", "--delimiter":
			delimiter = unescapeString(val)
		case "-0", "--delimiter0":
			delimiter0 = true
		case "-P", "--no-pager":
			noPager = true
		case "-q", "--quiet":
			quiet = true
		case "-s", "--sort":
			sortTerms = append(sortTerms, splitComma(val)...)
		case "-h", "--help":
			printTagListHelp()
			os.Exit(0)
		default:
			return false
		}
		return true
	})
	_ = remaining
	_ = noPager

	nb, err := openNotebook(workingDir)
	if err != nil {
		return err
	}
	defer nb.Close()

	var sorts []internal.TagSort
	for _, term := range sortTerms {
		s, err := internal.ParseTagSort(term)
		if err == nil {
			sorts = append(sorts, s)
		}
	}

	nb.IndexNotebook(internal.IndexOptions{Quiet: true})

	tags, err := nb.QueryTags(internal.TagFilter{}, sorts)
	if err != nil {
		return err
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	if header != "" {
		fmt.Fprint(writer, header)
	}

	isJSON := format == "json"
	isJSONL := format == "jsonl"

	if isJSON {
		fmt.Fprint(writer, "[")
	}

	for i, tag := range tags {
		if isJSON {
			b, _ := json.Marshal(internal.TagToJSON(tag))
			if i < len(tags)-1 {
				fmt.Fprintf(writer, "%s,", string(b))
			} else {
				fmt.Fprintf(writer, "%s", string(b))
			}
		} else if isJSONL {
			b, _ := json.Marshal(internal.TagToJSON(tag))
			fmt.Fprintln(writer, string(b))
		} else {
			formatted := internal.FormatTag(tag, format)
			if i > 0 {
				if delimiter0 {
					fmt.Fprint(writer, "\x00")
				} else {
					fmt.Fprint(writer, delimiter)
				}
			}
			fmt.Fprint(writer, formatted)
		}
	}

	if isJSON {
		fmt.Fprint(writer, "]\n")
	} else if !isJSONL && len(tags) > 0 {
		fmt.Fprintln(writer)
	}

	if footer != "" {
		fmt.Fprint(writer, footer)
	}

	if !quiet {
		fmt.Fprintf(os.Stderr, "\nFound %d tag%s\n", len(tags), pluralS(len(tags)))
	}

	return nil
}

