// parseFlags parses command-line flags and calls fn for each flag
// Returns remaining non-flag arguments
func parseFlags(args []string, fn func(flag, val string) bool) []string {
	var remaining []string
	i := 0
	for i < len(args) {
		arg := args[i]
		if !strings.HasPrefix(arg, "-") {
			remaining = append(remaining, arg)
			i++
			continue
		}

		// Long flag with = sign
		if eqIdx := strings.IndexByte(arg, '='); eqIdx > 0 {
			flag := arg[:eqIdx]
			val := arg[eqIdx+1:]
			if !fn(flag, val) {
				remaining = append(remaining, arg)
			}
			i++
			continue
		}

		// Check if flag takes a value
		flag := arg
		val := ""
		takesVal := flagTakesValue(flag)

		if takesVal && i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
			i++
			val = args[i]
		}

		if !fn(flag, val) {
			remaining = append(remaining, arg)
		}
		i++
	}
	return remaining
}

func flagTakesValue(flag string) bool {
	switch flag {
	case "-f", "--format", "--header", "--footer", "-d", "--delimiter",
		"-n", "--limit", "-m", "--match", "-M", "--match-strategy",
		"-x", "--exclude", "-t", "--tag", "-l", "--link-to",
		"--no-link-to", "-L", "--linked-by", "--no-linked-by",
		"--related", "--max-distance", "-s", "--sort",
		"--created", "--created-before", "--created-after",
		"--modified", "--modified-before", "--modified-after",
		"--mention", "--mentioned-by",
		"--template", "--extra", "--date", "--id", "-g", "--group",
		"-W", "--working-dir", "--notebook-dir",
		"--title", "-t": // -t is ambiguous but we handle both
		return true
	}
	return false
}

func unescapeString(s string) string {
	s = strings.ReplaceAll(s, `\n`, "\n")
	s = strings.ReplaceAll(s, `\t`, "\t")
	s = strings.ReplaceAll(s, `\0`, "\x00")
	return s
}

func splitComma(s string) []string {
	parts := strings.Split(s, ",")
	var result []string
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p != "" {
			result = append(result, p)
		}
	}
	return result
}

// resolveNotePath resolves a path argument to a notebook-relative path
func resolveNotePath(path, workingDir, notebookDir string) string {
	if !filepath.IsAbs(path) {
		path = filepath.Join(workingDir, path)
	}
	rel, err := filepath.Rel(notebookDir, path)
	if err != nil {
		return path
	}
	return filepath.ToSlash(rel)
}

func parseShellArgs(s string) []string {
	// Very simple shell arg parser - just split by spaces respecting quotes
	var args []string
	var cur strings.Builder
	inSingle := false
	inDouble := false

	for i := 0; i < len(s); i++ {
		c := s[i]
		if inSingle {
			if c == '\'' {
				inSingle = false
			} else {
				cur.WriteByte(c)
			}
		} else if inDouble {
			if c == '"' {
				inDouble = false
			} else {
				cur.WriteByte(c)
			}
		} else if c == '\'' {
			inSingle = true
		} else if c == '"' {
			inDouble = true
		} else if c == ' ' || c == '\t' {
			if cur.Len() > 0 {
				args = append(args, cur.String())
				cur.Reset()
			}
		} else {
			cur.WriteByte(c)
		}
	}
	if cur.Len() > 0 {
		args = append(args, cur.String())
	}
	return args
}

func runAlias(aliasCmd string, args []string, nb *internal.Notebook) error {
	// Replace $@ with the args
	argsStr := strings.Join(args, " ")
	aliasCmd = strings.ReplaceAll(aliasCmd, "$@", argsStr)

	// Set ZK_NOTEBOOK_DIR
	os.Setenv("ZK_NOTEBOOK_DIR", nb.RootDir)

	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "/bin/sh"
	}

	cmd := exec.Command(shell, "-c", aliasCmd)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}
