func cmdIndex(args []string, workingDir string) error {
	var force, verbose, quiet bool

	remaining := parseFlags(args, func(flag, val string) bool {
		switch flag {
		case "-f", "--force":
			force = true
		case "-v", "--verbose":
			verbose = true
		case "-q", "--quiet":
			quiet = true
		case "-h", "--help":
			printIndexHelp()
			os.Exit(0)
		default:
			return false
		}
		return true
	})
	_ = remaining

	nb, err := openNotebook(workingDir)
	if err != nil {
		return err
	}
	defer nb.Close()

	start := time.Now()
	stats, err := nb.IndexNotebook(internal.IndexOptions{
		Force:   force,
		Verbose: verbose,
		Quiet:   quiet,
	})
	if err != nil {
		return fmt.Errorf("indexing: %v", err)
	}
	elapsed := time.Since(start)

	if !quiet {
		totalStr := "s"
		if elapsed.Milliseconds() < 1000 {
			totalStr = "s"
		}
		fmt.Printf("Indexed %d note%s in %s\n", stats.Added+stats.Modified+stats.Removed+stats.Unchanged, 
			pluralS(stats.Added+stats.Modified+stats.Removed+stats.Unchanged),
			formatDuration(elapsed))
		fmt.Printf("  + %d added\n", stats.Added)
		fmt.Printf("  ~ %d modified\n", stats.Modified)
		fmt.Printf("  - %d removed\n", stats.Removed)
		_ = totalStr
	}

	return nil
}

func formatDuration(d time.Duration) string {
	if d < time.Second {
		return "0s"
	}
	return fmt.Sprintf("%ds", int(d.Seconds()))
}

func pluralS(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

