	for _, p := range linkedBy {
		resolved := resolveNotePath(p, workingDir, nb.RootDir)
		filter.LinkedBy = append(filter.LinkedBy, resolved)
	}
	for _, p := range noLinkedBy {
		resolved := resolveNotePath(p, workingDir, nb.RootDir)
		filter.NoLinkedBy = append(filter.NoLinkedBy, resolved)
	}

	// Parse dates
	if createdStr != "" {
		t, err := internal.ParseRelativeDate(createdStr)
		if err == nil {
			filter.Created = &t
		}
	}
	if createdBeforeStr != "" {
		t, err := internal.ParseRelativeDate(createdBeforeStr)
		if err == nil {
			filter.CreatedBefore = &t
		}
	}
	if createdAfterStr != "" {
		t, err := internal.ParseRelativeDate(createdAfterStr)
		if err == nil {
			filter.CreatedAfter = &t
		}
	}
	if modifiedStr != "" {
		t, err := internal.ParseRelativeDate(modifiedStr)
		if err == nil {
			filter.Modified = &t
		}
	}
	if modifiedBeforeStr != "" {
		t, err := internal.ParseRelativeDate(modifiedBeforeStr)
		if err == nil {
			filter.ModifiedBefore = &t
		}
	}
	if modifiedAfterStr != "" {
		t, err := internal.ParseRelativeDate(modifiedAfterStr)
		if err == nil {
			filter.ModifiedAfter = &t
		}
	}

	// Parse sorts
	var sorts []internal.NoteSort
	for _, term := range sortTerms {
		s, err := internal.ParseNoteSort(term)
		if err != nil {
			return fmt.Errorf("invalid sort term: %v", err)
		}
		sorts = append(sorts, s)
	}

	// Run index first
	nb.IndexNotebook(internal.IndexOptions{Quiet: true})

	notes, err := nb.QueryNotes(filter, sorts)
	if err != nil {
		return err
	}

	// Determine relative working dir
	relCwd, _ := filepath.Rel(nb.RootDir, workingDir)

	// Output
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	if header != "" {
		fmt.Fprint(writer, header)
	}

	isJSON := format == "json"
	isJSONL := format == "jsonl"

	if isJSON {
		fmt.Fprint(writer, "[\n")
	}

	for i, note := range notes {
		if isJSON {
			b, _ := json.Marshal(internal.NoteToJSON(note))
			if i < len(notes)-1 {
				fmt.Fprintf(writer, "%s,\n", string(b))
			} else {
				fmt.Fprintf(writer, "%s\n", string(b))
			}
		} else if isJSONL {
			b, _ := json.Marshal(internal.NoteToJSON(note))
			fmt.Fprintln(writer, string(b))
		} else {
			formatted := internal.FormatNote(note, format, relCwd, &nb.Config)
			if i > 0 {
				if delimiter0 {
					fmt.Fprint(writer, "\x00")
				} else {
					fmt.Fprint(writer, delimiter)
				}
			}
			fmt.Fprint(writer, formatted)
		}
	}

	if isJSON {
		fmt.Fprint(writer, "]\n")
	} else if !isJSONL && len(notes) > 0 {
		fmt.Fprintln(writer)
	}

	if footer != "" {
		fmt.Fprint(writer, footer)
	}

	if !quiet {
		fmt.Fprintf(os.Stderr, "\nFound %d note%s\n", len(notes), pluralS(len(notes)))
	}

	return nil
}

