		createdBeforeStr string
		createdAfterStr  string
		modifiedStr string
		modifiedBeforeStr string
		modifiedAfterStr  string
		sortTerms   []string
	)

	var pathArgs []string
	remaining := parseFlags(args, func(flag, val string) bool {
		switch flag {
		case "-f", "--format":
			format = val
		case "--header":
			header = val
		case "--footer":
			footer = unescapeString(val)
		case "-d", "--delimiter":
			delimiter = unescapeString(val)
		case "-0", "--delimiter0":
			delimiter0 = true
		case "-P", "--no-pager":
			noPager = true
		case "-q", "--quiet":
			quiet = true
		case "-i", "--interactive":
			interactive = true
		case "-n", "--limit":
			fmt.Sscanf(val, "%d", &limit)
		case "-m", "--match":
			match = val
		case "-M", "--match-strategy":
			matchStrategy = val
		case "-x", "--exclude":
			excludePaths = append(excludePaths, splitComma(val)...)
		case "-t", "--tag":
			tags = append(tags, splitComma(val)...)
		case "-l", "--link-to":
			linkTo = append(linkTo, splitComma(val)...)
		case "--no-link-to":
			noLinkTo = append(noLinkTo, splitComma(val)...)
		case "-L", "--linked-by":
			linkedBy = append(linkedBy, splitComma(val)...)
		case "--no-linked-by":
			noLinkedBy = append(noLinkedBy, splitComma(val)...)
		case "--orphan":
			orphan = true
		case "--tagless":
			tagless = true
		case "--missing-backlink":
			missingBacklink = true
		case "--related":
			related = append(related, splitComma(val)...)
		case "-r", "--recursive":
			recursive = true
		case "--created":
			createdStr = val
		case "--created-before":
			createdBeforeStr = val
		case "--created-after":
			createdAfterStr = val
		case "--modified":
			modifiedStr = val
		case "--modified-before":
			modifiedBeforeStr = val
		case "--modified-after":
			modifiedAfterStr = val
		case "-s", "--sort":
			sortTerms = append(sortTerms, splitComma(val)...)
		case "-h", "--help":
			printListHelp()
			os.Exit(0)
		default:
			return false
		}
		return true
	})

	for _, a := range remaining {
		if !strings.HasPrefix(a, "-") {
			pathArgs = append(pathArgs, a)
		}
	}

	_ = interactive
	_ = noPager
	_ = related
	_ = recursive

	nb, err := openNotebook(workingDir)
	if err != nil {
		return err
	}
	defer nb.Close()

	// Build filter
	filter := internal.NoteFilter{
		Tags:            tags,
		Match:           match,
		MatchStrategy:   matchStrategy,
		Limit:           limit,
		Orphan:          orphan,
		Tagless:         tagless,
		MissingBacklink: missingBacklink,
		ExcludePaths:    excludePaths,
	}

	// Resolve path args relative to working dir and notebook
	for _, p := range pathArgs {
		resolved := resolveNotePath(p, workingDir, nb.RootDir)
		filter.Paths = append(filter.Paths, resolved)
	}

	// Resolve link-to paths
	for _, p := range linkTo {
		resolved := resolveNotePath(p, workingDir, nb.RootDir)
		filter.LinkTo = append(filter.LinkTo, resolved)
	}
	for _, p := range noLinkTo {
		resolved := resolveNotePath(p, workingDir, nb.RootDir)
		filter.NoLinkTo = append(filter.NoLinkTo, resolved)
	}
	for _, p := range linkedBy {
		resolved := resolveNotePath(p, workingDir, nb.RootDir)
		filter.LinkedBy = append(filter.LinkedBy, resolved)
	}
	for _, p := range noLinkedBy {
		resolved := resolveNotePath(p, workingDir, nb.RootDir)
		filter.NoLinkedBy = append(filter.NoLinkedBy, resolved)
	}

	// Parse dates
	if createdStr != "" {
		t, err := internal.ParseRelativeDate(createdStr)
		if err == nil {
			filter.Created = &t
		}
	}
	if createdBeforeStr != "" {
		t, err := internal.ParseRelativeDate(createdBeforeStr)
		if err == nil {
			filter.CreatedBefore = &t
		}
	}
	if createdAfterStr != "" {
		t, err := internal.ParseRelativeDate(createdAfterStr)
		if err == nil {
			filter.CreatedAfter = &t
		}
	}
	if modifiedStr != "" {
		t, err := internal.ParseRelativeDate(modifiedStr)
		if err == nil {
			filter.Modified = &t
		}
	}
	if modifiedBeforeStr != "" {
		t, err := internal.ParseRelativeDate(modifiedBeforeStr)
		if err == nil {
			filter.ModifiedBefore = &t
		}
	}
	if modifiedAfterStr != "" {
		t, err := internal.ParseRelativeDate(modifiedAfterStr)
		if err == nil {
			filter.ModifiedAfter = &t
		}
	}

	// Parse sorts
	var sorts []internal.NoteSort
	for _, term := range sortTerms {
		s, err := internal.ParseNoteSort(term)
		if err != nil {
			return fmt.Errorf("invalid sort term: %v", err)
		}
		sorts = append(sorts, s)
	}

	// Run index first
	nb.IndexNotebook(internal.IndexOptions{Quiet: true})

	notes, err := nb.QueryNotes(filter, sorts)
	if err != nil {
		return err
	}

	// Determine relative working dir
	relCwd, _ := filepath.Rel(nb.RootDir, workingDir)

	// Output
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	if header != "" {
		fmt.Fprint(writer, header)
	}

	isJSON := format == "json"
	isJSONL := format == "jsonl"

	if isJSON {
		fmt.Fprint(writer, "[\n")
	}

	for i, note := range notes {
		if isJSON {
			b, _ := json.Marshal(internal.NoteToJSON(note))
			if i < len(notes)-1 {
				fmt.Fprintf(writer, "%s,\n", string(b))
			} else {
				fmt.Fprintf(writer, "%s\n", string(b))
			}
		} else if isJSONL {
			b, _ := json.Marshal(internal.NoteToJSON(note))
			fmt.Fprintln(writer, string(b))
		} else {
			formatted := internal.FormatNote(note, format, relCwd, &nb.Config)
			if i > 0 {
				if delimiter0 {
					fmt.Fprint(writer, "\x00")
				} else {
					fmt.Fprint(writer, delimiter)
				}
			}
			fmt.Fprint(writer, formatted)
		}
	}

	if isJSON {
		fmt.Fprint(writer, "]\n")
	} else if !isJSONL && len(notes) > 0 {
		fmt.Fprintln(writer)
	}

	if footer != "" {
		fmt.Fprint(writer, footer)
	}

	if !quiet {
		fmt.Fprintf(os.Stderr, "\nFound %d note%s\n", len(notes), pluralS(len(notes)))
	}

	return nil
}

