// cmdEdit implements the edit command
func cmdEdit(args []string, workingDir string) error {
	var (
		force     bool
		sortTerms []string
		// Same filters as list
		tags        []string
		limit       int
		match       string
		matchStrategy string
		excludePaths []string
		linkTo      []string
		noLinkTo    []string
		linkedBy    []string
		noLinkedBy  []string
		orphan      bool
		tagless     bool
		missingBacklink bool
		pathArgs    []string
	)

	remaining := parseFlags(args, func(flag, val string) bool {
		switch flag {
		case "-f", "--force":
			force = true
		case "-s", "--sort":
			sortTerms = append(sortTerms, splitComma(val)...)
		case "-t", "--tag":
			tags = append(tags, splitComma(val)...)
		case "-n", "--limit":
			fmt.Sscanf(val, "%d", &limit)
		case "-m", "--match":
			match = val
		case "-M", "--match-strategy":
			matchStrategy = val
		case "-x", "--exclude":
			excludePaths = append(excludePaths, splitComma(val)...)
		case "-l", "--link-to":
			linkTo = append(linkTo, splitComma(val)...)
		case "--no-link-to":
			noLinkTo = append(noLinkTo, splitComma(val)...)
		case "-L", "--linked-by":
			linkedBy = append(linkedBy, splitComma(val)...)
		case "--no-linked-by":
			noLinkedBy = append(noLinkedBy, splitComma(val)...)
		case "--orphan":
			orphan = true
		case "--tagless":
			tagless = true
		case "--missing-backlink":
			missingBacklink = true
		case "-h", "--help":
			printEditHelp()
			os.Exit(0)
		default:
			return false
		}
		return true
	})
	for _, a := range remaining {
		if !strings.HasPrefix(a, "-") {
			pathArgs = append(pathArgs, a)
		}
	}

	_ = force

	nb, err := openNotebook(workingDir)
	if err != nil {
		return err
	}
	defer nb.Close()

	filter := internal.NoteFilter{
		Tags:            tags,
		Match:           match,
		MatchStrategy:   matchStrategy,
		Limit:           limit,
		Orphan:          orphan,
		Tagless:         tagless,
		MissingBacklink: missingBacklink,
		ExcludePaths:    excludePaths,
	}
	for _, p := range pathArgs {
		resolved := resolveNotePath(p, workingDir, nb.RootDir)
		filter.Paths = append(filter.Paths, resolved)
	}
	for _, p := range linkTo {
		filter.LinkTo = append(filter.LinkTo, resolveNotePath(p, workingDir, nb.RootDir))
	}
	for _, p := range noLinkTo {
		filter.NoLinkTo = append(filter.NoLinkTo, resolveNotePath(p, workingDir, nb.RootDir))
	}
	for _, p := range linkedBy {
		filter.LinkedBy = append(filter.LinkedBy, resolveNotePath(p, workingDir, nb.RootDir))
	}
	for _, p := range noLinkedBy {
		filter.NoLinkedBy = append(filter.NoLinkedBy, resolveNotePath(p, workingDir, nb.RootDir))
	}

	var sorts []internal.NoteSort
	for _, term := range sortTerms {
		s, err := internal.ParseNoteSort(term)
		if err == nil {
			sorts = append(sorts, s)
		}
	}

	nb.IndexNotebook(internal.IndexOptions{Quiet: true})

	notes, err := nb.QueryNotes(filter, sorts)
	if err != nil {
		return err
	}

	if len(notes) == 0 {
		return nil
	}

	// Build list of paths
	var paths []string
	for _, n := range notes {
		paths = append(paths, n.AbsPath)
	}

	editor := nb.Config.Tool.Editor
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		editor = os.Getenv("VISUAL")
	}

	if editor != "" {
		cmdStr := editor + " " + strings.Join(quoteArgs(paths), " ")
		cmd := exec.Command("sh", "-c", cmdStr)
		cmd.Stdin = os.Stdin
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		return cmd.Run()
	}

	return nil
}

func quoteArgs(args []string) []string {
	var result []string
	for _, a := range args {
		result = append(result, `"`+a+`"`)
	}
	return result
}

