// cmdTagList implements the tag list command
func cmdTagList(args []string, workingDir string) error {
	var (
		format    string
		header    string
		footer    = "\n"
		delimiter = "\n"
		delimiter0 bool
		noPager   bool
		quiet     bool
		sortTerms []string
	)

	remaining := parseFlags(args, func(flag, val string) bool {
		switch flag {
		case "-f", "--format":
			format = val
		case "--header":
			header = val
		case "--footer":
			footer = unescapeString(val)
		case "-d", "--delimiter":
			delimiter = unescapeString(val)
		case "-0", "--delimiter0":
			delimiter0 = true
		case "-P", "--no-pager":
			noPager = true
		case "-q", "--quiet":
			quiet = true
		case "-s", "--sort":
			sortTerms = append(sortTerms, splitComma(val)...)
		case "-h", "--help":
			printTagListHelp()
			os.Exit(0)
		default:
			return false
		}
		return true
	})
