	tags, err := nb.QueryTags(internal.TagFilter{}, sorts)
	if err != nil {
		return err
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	if header != "" {
		fmt.Fprint(writer, header)
	}

	isJSON := format == "json"
	isJSONL := format == "jsonl"

	if isJSON {
		fmt.Fprint(writer, "[")
	}

	for i, tag := range tags {
		if isJSON {
			b, _ := json.Marshal(internal.TagToJSON(tag))
			if i < len(tags)-1 {
				fmt.Fprintf(writer, "%s,", string(b))
			} else {
				fmt.Fprintf(writer, "%s", string(b))
			}
		} else if isJSONL {
			b, _ := json.Marshal(internal.TagToJSON(tag))
			fmt.Fprintln(writer, string(b))
		} else {
			formatted := internal.FormatTag(tag, format)
			if i > 0 {
				if delimiter0 {
					fmt.Fprint(writer, "\x00")
				} else {
					fmt.Fprint(writer, delimiter)
				}
			}
			fmt.Fprint(writer, formatted)
		}
	}

	if isJSON {
		fmt.Fprint(writer, "]\n")
	} else if !isJSONL && len(tags) > 0 {
		fmt.Fprintln(writer)
	}

	if footer != "" {
		fmt.Fprint(writer, footer)
	}

	if !quiet {
		fmt.Fprintf(os.Stderr, "\nFound %d tag%s\n", len(tags), pluralS(len(tags)))
	}

