func NoteToJSON(note NoteResult) map[string]interface{} {
	tags := note.Tags
	if tags == nil {
		tags = []string{}
	}

	meta := note.Metadata
	if meta == nil {
		meta = make(map[string]interface{})
	}

	// Build snippets as interface{} slice
	var snippetsIF []interface{}
	for _, s := range note.Snippets {
		snippetsIF = append(snippetsIF, s)
	}
	if snippetsIF == nil {
		snippetsIF = []interface{}{}
	}

	return map[string]interface{}{
		"filename":     note.Filename,
		"filenameStem": note.FilenameStem,
		"path":         note.Path,
		"absPath":      note.AbsPath,
		"title":        note.Title,
		"link":         note.Link,
		"lead":         note.Lead,
