// resolveLinks resolves any unresolved links (target_id = NULL, external = 0)
func (nb *Notebook) resolveLinks() error {
	// Get all notes path -> id mapping
	rows, err := nb.DB.QueryRows("SELECT id, path FROM notes")
	if err != nil {
		return err
	}
	pathToID := make(map[string]int64)
