		if v, ok := row["id"]; ok {
			if n, ok := v.(int64); ok {
				id = n
			}
		}
		path := ""
		if v, ok := row["path"]; ok {
			if s, ok := v.(string); ok {
				path = s
			}
		}
		pathToID[path] = id
	}

	// Get all unresolved links
	unresolvedLinks, err := nb.DB.QueryRows(
		"SELECT id, source_id, href, type FROM links WHERE target_id IS NULL AND external = 0",
	)
	if err != nil {
		return err
	}

	for _, link := range unresolvedLinks {
		linkID := int64(0)
		if v, ok := link["id"]; ok {
			if n, ok := v.(int64); ok {
				linkID = n
			}
		}
		sourceID := int64(0)
		if v, ok := link["source_id"]; ok {
			if n, ok := v.(int64); ok {
				sourceID = n
			}
		}
		href := ""
		if v, ok := link["href"]; ok {
			if s, ok := v.(string); ok {
				href = s
			}
		}
		linkType := ""
		if v, ok := link["type"]; ok {
			if s, ok := v.(string); ok {
				linkType = s
			}
		}

		// Get source path
		sourceRow, err := nb.DB.QueryRow("SELECT path FROM notes WHERE id = ?", sourceID)
		if err != nil || sourceRow == nil {
			continue
		}
		sourcePath := ""
		if v, ok := sourceRow["path"]; ok {
			if s, ok := v.(string); ok {
				sourcePath = s
			}
		}

		// Try to resolve the link
		targetPath := resolveLink(href, linkType, sourcePath, pathToID)
		if targetPath != "" {
			if targetID, ok := pathToID[targetPath]; ok {
				nb.DB.Exec("UPDATE links SET target_id = ? WHERE id = ?", targetID, linkID)
			}
		}
	}
	return nil
}
